import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface StudentDataRow {
  user_id: string | number;
  real_name: string;
  package_grade: string;
  counselor_name: string;

  // Unit details
  unit_sequence: number; // e.g., 1, 2, 3, 4
  unit_finish_status: string; // "完课" or others
  first_cost_seconds: number | string; // Time spent
  answer_right_rate: string | number; // e.g., "80.00%" or 0.8

  // Timestamps (optional based on usage)
  first_finish_time?: string;

  // Any other fields from the excel that might be useful
  [key: string]: any;
}

export interface ProcessedReportData {
  studentName: string;
  grade: string;
  teacher: string;
  totalTimeSeconds: number;
  completedUnitsCount: number;
  units: UnitData[];
}

export interface UnitData {
  unitNumber: number;
  unitName: string;
  timeSpentSeconds: number;
  status: 'completed' | 'pending'; // Derived from unit_finish_status
  statusRaw: string;
  accuracy: number; // 0-100
  analysis: string; // Derived analysis text
}

import { StudentDataRow, ProcessedReportData, UnitData } from './types';

export const formatDuration = (seconds: number): string => {
  if (!seconds || isNaN(seconds)) return '0';
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  if (mins === 0) return `${secs}秒`;
  return `${mins}分${secs}秒`;
};

export const parseRate = (rate: string | number): number => {
  if (typeof rate === 'number') return rate * 100;
  if (typeof rate === 'string') {
    if (rate.includes('%')) {
      return parseFloat(rate.replace('%', ''));
    }
    const val = parseFloat(rate);
    return val <= 1 ? val * 100 : val;
  }
  return 0;
};

export const processExcelData = (rows: StudentDataRow[]): ProcessedReportData | null => {
  if (!rows || rows.length === 0) return null;

  // Assume the file contains data for one student or we pick the first one found.
  // Grouping by user_id or real_name. Let's pick the first row's student.
  const primaryStudent = rows[0].real_name;
  const studentRows = rows.filter(r => r.real_name === primaryStudent);

  // Sort by unit sequence
  studentRows.sort((a, b) => (a.unit_sequence || 0) - (b.unit_sequence || 0));

  const units: UnitData[] = studentRows.map((row) => {
    const isCompleted = row.unit_finish_status === '完课';
    const accuracy = parseRate(row.answer_right_rate);

    // Determine analysis based on accuracy
    let analysis = '待学习';
    if (isCompleted) {
        if (accuracy >= 85) analysis = '知识点掌握稳定';
        else if (accuracy >= 60) analysis = '掌握一般';
        else analysis = '正确率相对较低，为薄弱单元';
    } else if (row.unit_finish_status === '未到课' || row.unit_finish_status === '待学习') {
        analysis = '本讲内容需要学习';
    }

    return {
      unitNumber: row.unit_sequence,
      unitName: `第${row.unit_sequence}单元`,
      timeSpentSeconds: Number(row.first_cost_seconds) || 0,
      status: isCompleted ? 'completed' : 'pending',
      statusRaw: row.unit_finish_status,
      accuracy: accuracy,
      analysis: analysis
    };
  });

  // Aggregate totals
  const totalTime = units.reduce((acc, curr) => acc + curr.timeSpentSeconds, 0);
  const completedCount = units.filter(u => u.status === 'completed').length;

  return {
    studentName: studentRows[0].real_name,
    grade: studentRows[0].package_grade,
    teacher: studentRows[0].counselor_name,
    totalTimeSeconds: totalTime,
    completedUnitsCount: completedCount,
    units
  };
};

import React from 'react';
