import React, { useCallback } from 'react';
import * as XLSX from 'xlsx';
import { Upload } from 'lucide-react';
import { StudentDataRow } from '../types';

interface Props {
  onDataLoaded: (data: StudentDataRow[]) => void;
}

const FileUpload: React.FC<Props> = ({ onDataLoaded }) => {
  const handleFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json<StudentDataRow>(ws);
      onDataLoaded(data);
    };
    reader.readAsBinaryString(file);
  }, [onDataLoaded]);

  return (
    <div className="max-w-xl mx-auto mt-20 p-8 bg-white rounded-xl shadow-lg border-2 border-dashed border-blue-200 text-center">
      <div className="flex flex-col items-center gap-4">
        <div className="p-4 bg-blue-50 rounded-full">
          <Upload className="w-10 h-10 text-blue-500" />
        </div>
        <h2 className="text-xl font-bold text-gray-800">上传学习数据 Excel</h2>
        <p className="text-gray-500 text-sm mb-4">
          请上传包含学生学习记录的 Excel 表格 (.xlsx, .xls)<br/>
          系统将自动读取第一位学生的记录生成报告。
        </p>

        <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg transition-colors shadow-md">
          <span>选择文件</span>
          <input 
            type="file" 
            accept=".xlsx, .xls" 
            className="hidden" 
            onChange={handleFileChange} 
          />
        </label>

        <div className="mt-6 text-left w-full bg-gray-50 p-4 rounded text-xs text-gray-500">
          <p className="font-semibold mb-1">支持的表头字段 (示例):</p>
          <code className="break-all">real_name, package_grade, counselor_name, unit_sequence, unit_finish_status, first_cost_seconds, answer_right_rate...</code>
        </div>
      </div>
    </div>
  );
};

export default FileUpload;

import React, { useState } from 'react';
