import { StudentDataRow, ProcessedReportData, UnitData } from './types';

export const formatDuration = (seconds: number): string => {
  if (!seconds || isNaN(seconds)) return '0';
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  if (mins === 0) return `${secs}秒`;
  return `${mins}分${secs}秒`;
};

export const parseRate = (rate: string | number): number => {
  if (typeof rate === 'number') return rate * 100;
  if (typeof rate === 'string') {
    if (rate.includes('%')) {
      return parseFloat(rate.replace('%', ''));
    }
    const val = parseFloat(rate);
    return val <= 1 ? val * 100 : val;
  }
  return 0;
};

// Required columns for the app to function correctly
const REQUIRED_COLUMNS = ['real_name', 'unit_sequence', 'unit_finish_status', 'answer_right_rate'];

export const validateExcelData = (rows: any[]): { valid: boolean; error?: string } => {
  if (!rows || rows.length === 0) {
    return { valid: false, error: '文件为空或无法解析数据' };
  }

  const firstRow = rows[0];
  const missingColumns = REQUIRED_COLUMNS.filter(col => !(col in firstRow));

  if (missingColumns.length > 0) {
    return { 
      valid: false, 
      error: `缺少必要表头字段: ${missingColumns.join(', ')}。请检查 Excel 格式。` 
    };
  }

  return { valid: true };
};

export interface StudentSummary {
  name: string;
  grade: string;
  teacher: string;
  unitCount: number;
  lastUnit: string | number;
}

export const getStudentSummaries = (rows: StudentDataRow[]): StudentSummary[] => {
  const map = new Map<string, StudentSummary>();

  rows.forEach(row => {
    if (!row.real_name) return;

    if (!map.has(row.real_name)) {
      map.set(row.real_name, {
        name: row.real_name,
        grade: row.package_grade || '未知年级',
        teacher: row.counselor_name || '未知老师',
        unitCount: 0,
        lastUnit: 0
      });
    }

    const summary = map.get(row.real_name)!;
    summary.unitCount += 1;
    if (row.unit_sequence && Number(row.unit_sequence) > Number(summary.lastUnit)) {
      summary.lastUnit = row.unit_sequence;
    }
  });

  return Array.from(map.values());
};

export const processExcelData = (rows: StudentDataRow[], targetStudentName?: string): ProcessedReportData | null => {
  if (!rows || rows.length === 0) return null;

  // If a specific student is requested, use them. Otherwise default to the first one found.
  const primaryStudent = targetStudentName || rows[0].real_name;

  const studentRows = rows.filter(r => r.real_name === primaryStudent);

  if (studentRows.length === 0) return null;

  // Sort by unit sequence
  studentRows.sort((a, b) => (a.unit_sequence || 0) - (b.unit_sequence || 0));

  const units: UnitData[] = studentRows.map((row) => {
    const isCompleted = row.unit_finish_status === '完课';
    const accuracy = parseRate(row.answer_right_rate);

    // Determine analysis based on accuracy
    let analysis = '待学习';
    if (isCompleted) {
        if (accuracy >= 85) analysis = '知识点掌握稳定';
        else if (accuracy >= 60) analysis = '掌握一般';
        else analysis = '正确率相对较低，为薄弱单元';
    } else if (row.unit_finish_status === '未到课' || row.unit_finish_status === '待学习') {
        analysis = '本讲内容需要学习';
    }

    return {
      unitNumber: row.unit_sequence,
      unitName: `第${row.unit_sequence}单元`,
      timeSpentSeconds: Number(row.first_cost_seconds) || 0,
      status: isCompleted ? 'completed' : 'pending',
      statusRaw: row.unit_finish_status,
      accuracy: accuracy,
      analysis: analysis
    };
  });

  // Aggregate totals
  const totalTime = units.reduce((acc, curr) => acc + curr.timeSpentSeconds, 0);
  const completedCount = units.filter(u => u.status === 'completed').length;

  return {
    studentName: studentRows[0].real_name,
    grade: studentRows[0].package_grade,
    teacher: studentRows[0].counselor_name,
    totalTimeSeconds: totalTime,
    completedUnitsCount: completedCount,
    units
  };
};

import React, { useCallback, useState } from 'react';
import * as XLSX from 'xlsx';
import { Upload, AlertCircle, FileText } from 'lucide-react';
import { StudentDataRow } from '../types';
import { validateExcelData } from '../utils';

interface Props {
  onDataLoaded: (data: StudentDataRow[]) => void;
}

const FileUpload: React.FC<Props> = ({ onDataLoaded }) => {
  const [error, setError] = useState<string | null>(null);
  const [dragActive, setDragActive] = useState(false);

  const processFile = (file: File) => {
    setError(null);
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json<StudentDataRow>(ws);

        const validation = validateExcelData(data);
        if (!validation.valid) {
          setError(validation.error || '文件格式无效');
          return;
        }

        onDataLoaded(data);
      } catch (err) {
        console.error(err);
        setError('解析文件时出错，请确保文件未损坏且格式正确。');
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) processFile(file);
  }, [onDataLoaded]);

  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  }, [onDataLoaded]);

  return (
    <div className="max-w-xl mx-auto mt-20">
      <div 
        className={`p-8 bg-white rounded-xl shadow-lg border-2 border-dashed transition-all
          ${dragActive ? 'border-blue-500 bg-blue-50' : 'border-blue-200'}
          ${error ? 'border-red-200' : ''}`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
      >
        <div className="flex flex-col items-center gap-4 text-center">
          <div className={`p-4 rounded-full ${error ? 'bg-red-50' : 'bg-blue-50'}`}>
            {error ? (
              <AlertCircle className="w-10 h-10 text-red-500" />
            ) : (
              <Upload className="w-10 h-10 text-blue-500" />
            )}
          </div>

          <h2 className="text-xl font-bold text-gray-800">
            {error ? '验证失败' : '上传学习数据 Excel'}
          </h2>

          <p className="text-gray-500 text-sm mb-2">
            请上传包含学生学习记录的 Excel 表格 (.xlsx, .xls)
          </p>

          {error && (
             <div className="bg-red-50 border border-red-100 text-red-600 text-sm p-3 rounded-lg w-full mb-2">
               {error}
             </div>
          )}

          <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-6 py-2 rounded-lg transition-colors shadow-md flex items-center gap-2">
            <FileText className="w-4 h-4" />
            <span>选择文件</span>
            <input 
              type="file" 
              accept=".xlsx, .xls" 
              className="hidden" 
              onChange={handleFileChange} 
            />
          </label>

          <div className="mt-6 text-left w-full bg-gray-50 p-4 rounded text-xs text-gray-500">
            <p className="font-semibold mb-2 text-gray-700">必需表头字段:</p>
            <div className="grid grid-cols-2 gap-2 font-mono">
                <div>real_name</div>
                <div>unit_sequence</div>
                <div>unit_finish_status</div>
                <div>answer_right_rate</div>
            </div>
            <p className="font-semibold mt-3 mb-1 text-gray-700">可选字段:</p>
            <div className="font-mono">package_grade, counselor_name</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default FileUpload;

import React, { useState, useMemo } from 'react';
import { StudentDataRow } from '../types';
import { getStudentSummaries } from '../utils';
