            <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none">
              <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
            </div>
          </div>
        </div>
      </div>

      {/* Results Table */}
      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-gray-50 border-b border-gray-200 text-gray-500 uppercase font-medium text-xs">
              <tr>
                <th className="px-6 py-4">学生姓名</th>
                <th className="px-6 py-4">年级</th>
                <th className="px-6 py-4">辅导老师</th>
                <th className="px-6 py-4 text-center">记录数</th>
                <th className="px-6 py-4 text-center">最新进度</th>
                <th className="px-6 py-4 text-right">操作</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredStudents.length > 0 ? (
                filteredStudents.map((student) => (
                  <tr key={student.name} className="hover:bg-gray-50 transition-colors group">
                    <td className="px-6 py-4 font-semibold text-gray-800">
                      {student.name}
