const CLASS_AVG_ACCURACY = 85;

export const formatDuration = (seconds: number): string => {
  if (!seconds || isNaN(seconds)) return '0分钟';
  const hours = Math.floor(seconds / 3600);
  const remainingSeconds = seconds % 3600;
  const mins = Math.ceil(remainingSeconds / 60); // Round up for "minutes"

  if (hours > 0) {
    return `${hours}小时${mins > 0 ? ` ${mins}分钟` : ''}`;
  }
  return `${mins}分钟`;
};

// Simple helper for "X minutes" format used in summaries
const toMinutes = (seconds: number): number => Math.ceil(seconds / 60);

export const parseRate = (rate: string | number): number => {
  if (typeof rate === 'number') return rate * 100;
  if (typeof rate === 'string') {
    if (rate.includes('%')) {
      return parseFloat(rate.replace('%', ''));
    }
    const val = parseFloat(rate);
    return val <= 1 ? val * 100 : val;
  }
  return 0;
};

