const getAccuracyBadge = (avgAcc: number): Badge => {
  if (avgAcc >= 90) return { name: '学习典范', type: 'accuracy', level: 'model', description: '你的学习质量极高，思路清晰严谨，已展现出典范级的知识掌握力' };
  if (avgAcc >= 80) return { name: '稳定高手', type: 'accuracy', level: 'master', description: '稳定且扎实！高正确率反映了你良好的理解力和持续的学习态度。' };
  if (avgAcc >= 60) return { name: '进步之星', type: 'accuracy', level: 'progress', description: '正在稳步提升中！你的努力已见成效，继续保持这样的学习节奏。' };
  if (avgAcc >= 50) return { name: '潜力小将', type: 'accuracy', level: 'potential', description: '已顺利入门，掌握了核心方法。多一份细心，正确率会有明显提升。' };
  return { name: '成长启航', type: 'accuracy', level: 'growth', description: '学习之路，每一步都算数。积累经验、梳理方法，下一次会更好。' };
};

const analyzeTrend = (units: UnitData[]): TrendAnalysis => {
  if (units.length < 2) return { status: 'stable', title: '表现平稳', content: '数据较少，建议持续学习以积累更多数据。' };

  const validUnits = units.filter(u => u.status === 'high');
  if (validUnits.length < 2) return { status: 'growth', title: '蓄势待发', content: '完成课程较少，加油完成更多课程以解锁趋势分析！' };

  const accs = validUnits.map(u => u.accuracy);
  const allAboveAvg = accs.every(a => a >= CLASS_AVG_ACCURACY);
  const allBelowAvg = accs.every(a => a < CLASS_AVG_ACCURACY);

  // Simple linear slope approx
  const first = accs[0];
  const last = accs[accs.length - 1];
  const slope = last - first;
  const isIncreasing = slope > 3; // meaningful increase
  const isStable = Math.abs(slope) <= 5;

  // Rule 1: Always > Avg & Increasing
  if (allAboveAvg && isIncreasing) {
    return { status: 'excellent', title: '表现优秀且持续进步！', content: '单元的正确率均高于班级平均水平，并呈稳步上升趋势，展现扎实的掌握能力和良好的学习节奏。' };
  }
  // Rule 2: Always > Avg & Fluctuating (Not strict increasing)
  if (allAboveAvg) {
    return { status: 'stable_high', title: '整体表现稳定领先！', content: '虽然单元间略有波动，但全程均高于班级平均线，说明基础扎实，若能加强波动单元的巩固，表现将更出色。' };
  }
  // Rule 3: Start < Avg, End > Avg (Improving)
  if (first < CLASS_AVG_ACCURACY && last > CLASS_AVG_ACCURACY) {
    return { status: 'catch_up', title: '进步显著，后劲十足！', content: '从前期稍显生疏到后期稳步超越班级平均，体现了良好的适应能力和反思改进的学习态度。' };
  }
  // Rule 4: Stable around Avg (within +/- 10% range of avg roughly)
  const avgDist = accs.reduce((sum, a) => sum + Math.abs(a - CLASS_AVG_ACCURACY), 0) / accs.length;
  if (avgDist < 10) {
    return { status: 'stable_avg', title: '表现稳定，跟紧班级步伐', content: '各单元正确率与班级平均非常接近，若能进一步突破薄弱环节，有望实现领先。' };
  }
  // Rule 5: Always < Avg & Increasing
  if (allBelowAvg && isIncreasing) {
    return { status: 'improving', title: '虽暂未超越平均，但已步入上升通道！', content: '正确率逐单元提升，显示你正在逐步掌握方法，请保持当前学习节奏，加强复习。' };
  }

  // Fallback
  return { status: 'fluctuating', title: '学习状态略有波动', content: '正确率起伏较大，建议复习薄弱单元，找出知识盲区，争取下阶段稳步提升。' };
};

// --- Main Process Function ---

export const processExcelData = (rows: StudentDataRow[], targetStudentName?: string): ProcessedReportData | null => {
  if (!rows || rows.length === 0) return null;

  const primaryStudent = targetStudentName || rows[0].real_name;
  const studentRows = rows.filter(r => r.real_name === primaryStudent);
  if (studentRows.length === 0) return null;

  // Sort by unit sequence
  studentRows.sort((a, b) => (a.unit_sequence || 0) - (b.unit_sequence || 0));

  // Process Units
  const units: UnitData[] = studentRows.map((row) => {
    // Determine High/Low Completion. 
    // Logic: "完课" -> High (High Completion), Others -> Low (Low Completion/Pending)
    const isHigh = row.unit_finish_status === '完课';
    const accuracy = parseRate(row.answer_right_rate);
    const timeSpent = Number(row.first_cost_seconds) || 0;

    let analysis = '';
    // Analysis Rules
    if (!isHigh) {
      analysis = '【知识版块】等你挑战';
    } else {
      if (accuracy >= CLASS_AVG_ACCURACY) {
        analysis = '掌握扎实，超越平均';
      } else {
        analysis = '态度认真，请巩固错题';
      }
    }

    return {
      unitNumber: row.unit_sequence,
      unitName: `第${row.unit_sequence}单元`,
      timeSpentSeconds: timeSpent,
      status: isHigh ? 'high' : 'low',
      statusLabel: isHigh ? '高完课' : '低完课',
      accuracy,
      analysis
    };
  });

  // Calculate Aggregates
  const totalTimeSeconds = units.reduce((acc, u) => acc + u.timeSpentSeconds, 0);
  const avgTimeSeconds = units.length > 0 ? totalTimeSeconds / units.length : 0;

  const highCompletionCount = units.filter(u => u.status === 'high').length;
  const highUnits = units.filter(u => u.status === 'high');
  const avgAccuracy = highUnits.length > 0 
    ? highUnits.reduce((acc, u) => acc + u.accuracy, 0) / highUnits.length 
    : 0;

  // Generate Badges
  const completionBadge = getCompletionBadge(highCompletionCount);
  const accuracyBadge = getAccuracyBadge(avgAccuracy);

  // Generate Trend Analysis
  const trendAnalysis = analyzeTrend(units);

  // Generate Monthly Summary
  const highlights = units
    .filter(u => u.status === 'high' && u.accuracy >= CLASS_AVG_ACCURACY)
    .map(u => u.unitName);

  const improvements = units
    .filter(u => u.status === 'high' && u.accuracy < CLASS_AVG_ACCURACY)
    .map(u => u.unitName);

  const monthlySummary: MonthlySummary = {
    milestone: `本月你累计学习 ${toMinutes(totalTimeSeconds)} 分钟，完成【${highCompletionCount}个知识点】相当于攻克了${highCompletionCount * 5}个高频易错点，扫清年级知识盲区。每一分钟，都在把薄弱变成强项。`,
    highlights: highlights.length > 0 ? [`【知识版块】表现突出，正确率持续领先，思路清晰。`] : [],
    improvements: improvements.length > 0 ? [`【知识版块】正确率暂时落后，建议加强读题训练与综合运用，随时和老师预约小灶课。`] : []
  };

  return {
    studentName: studentRows[0].real_name,
    grade: studentRows[0].package_grade,
    teacher: studentRows[0].counselor_name,
    totalTimeSeconds,
    avgTimePerSession: avgTimeSeconds,
    timeComment: `一节课${Math.ceil(avgTimeSeconds/60)}分钟，短时高效，每天练出思维力！`,
    completionBadge,
    accuracyBadge,
    completedUnitsCount: highCompletionCount,
    units,
    trendAnalysis,
    monthlySummary
  };
};

export { validateExcelData, getStudentSummaries } from './utils_original'; // Re-export previous helpers if needed, but easier to include them below
// Re-including the validation and summary functions here for a complete file replacement
const REQUIRED_COLUMNS = ['real_name', 'unit_sequence', 'unit_finish_status', 'answer_right_rate'];

export const validateExcelData = (rows: any[]): { valid: boolean; error?: string } => {
  if (!rows || rows.length === 0) {
    return { valid: false, error: '文件为空或无法解析数据' };
  }
  const firstRow = rows[0];
  const missingColumns = REQUIRED_COLUMNS.filter(col => !(col in firstRow));
  if (missingColumns.length > 0) {
    return { valid: false, error: `缺少必要表头字段: ${missingColumns.join(', ')}。` };
  }
  return { valid: true };
};

export interface StudentSummary {
  name: string;
  grade: string;
  teacher: string;
  unitCount: number;
  lastUnit: string | number;
}

export const getStudentSummaries = (rows: StudentDataRow[]): StudentSummary[] => {
  const map = new Map<string, StudentSummary>();
  rows.forEach(row => {
    if (!row.real_name) return;
    if (!map.has(row.real_name)) {
      map.set(row.real_name, {
        name: row.real_name,
        grade: row.package_grade || '未知年级',
        teacher: row.counselor_name || '未知老师',
        unitCount: 0,
        lastUnit: 0
      });
    }
    const summary = map.get(row.real_name)!;
    summary.unitCount += 1;
    if (row.unit_sequence && Number(row.unit_sequence) > Number(summary.lastUnit)) {
      summary.lastUnit = row.unit_sequence;
    }
  });
  return Array.from(map.values());
};

