  if (avgAcc >= 80) return { name: '稳定高手', type: 'accuracy', level: 'master', description: '稳定且扎实！高正确率反映了你良好的理解力和持续的学习态度。' };
  if (avgAcc >= 60) return { name: '进步之星', type: 'accuracy', level: 'progress', description: '正在稳步提升中！你的努力已见成效，继续保持这样的学习节奏。' };
  if (avgAcc >= 50) return { name: '潜力小将', type: 'accuracy', level: 'potential', description: '已顺利入门，掌握了核心方法。多一份细心，正确率会有明显提升。' };
  return { name: '成长启航', type: 'accuracy', level: 'growth', description: '学习之路，每一步都算数。积累经验、梳理方法，下一次会更好。' };
};

const analyzeTrend = (units: UnitData[]): TrendAnalysis => {
  if (units.length < 2) return { status: 'stable', title: '表现平稳', content: '数据较少，建议持续学习以积累更多数据。' };

  const validUnits = units.filter(u => u.status === 'high');
  if (validUnits.length < 2) return { status: 'growth', title: '蓄势待发', content: '完成课程较少，加油完成更多课程以解锁趋势分析！' };

  const accs = validUnits.map(u => u.accuracy);
  const allAboveAvg = accs.every(a => a >= CLASS_AVG_ACCURACY);
  const allBelowAvg = accs.every(a => a < CLASS_AVG_ACCURACY);

  const first = accs[0];
  const last = accs[accs.length - 1];
  const slope = last - first;
  const isIncreasing = slope > 3; // meaningful increase

  // Rule 1: Always > Avg & Increasing
  if (allAboveAvg && isIncreasing) {
    return { status: 'excellent', title: '表现优秀且持续进步！', content: '单元的正确率均高于班级平均水平，并呈稳步上升趋势，展现扎实的掌握能力和良好的学习节奏。' };
  }
  // Rule 2: Always > Avg & Fluctuating (Not strict increasing)
  if (allAboveAvg) {
    return { status: 'stable_high', title: '整体表现稳定领先！', content: '虽然单元间略有波动，但全程均高于班级平均线，说明基础扎实，若能加强波动单元的巩固，表现将更出色。' };
  }
  // Rule 3: Start < Avg, End > Avg (Improving)
  if (first < CLASS_AVG_ACCURACY && last > CLASS_AVG_ACCURACY) {
    return { status: 'catch_up', title: '进步显著，后劲十足！', content: '从前期稍显生疏到后期稳步超越班级平均，体现了良好的适应能力和反思改进的学习态度。' };
  }
  // Rule 4: Stable around Avg (within +/- 10% range of avg roughly)
  const avgDist = accs.reduce((sum, a) => sum + Math.abs(a - CLASS_AVG_ACCURACY), 0) / accs.length;
  if (avgDist < 10) {
    return { status: 'stable_avg', title: '表现稳定，跟紧班级步伐', content: '各单元正确率与班级平均非常接近，若能进一步突破薄弱环节，有望实现领先。' };
  }
  // Rule 5: Always < Avg & Increasing
  if (allBelowAvg && isIncreasing) {
    return { status: 'improving', title: '虽暂未超越平均，但已步入上升通道！', content: '正确率逐单元提升，显示你正在逐步掌握方法，请保持当前学习节奏，加强复习。' };
  }

  // Fallback
  return { status: 'fluctuating', title: '学习状态略有波动', content: '正确率起伏较大，建议复习薄弱单元，找出知识盲区，争取下阶段稳步提升。' };
};

// --- Main Process Function ---

export const processExcelData = (rows: StudentDataRow[], targetStudentName?: string): ProcessedReportData | null => {
  if (!rows || rows.length === 0) return null;

  const primaryStudent = targetStudentName || rows[0].real_name;
  const studentRows = rows.filter(r => r.real_name === primaryStudent);
  if (studentRows.length === 0) return null;

  // Group by unit_sequence
  const unitsMap = new Map<number, StudentDataRow[]>();
  studentRows.forEach(row => {
    // Ensure unit_sequence is a number
    const seq = parseInt(String(row.unit_sequence), 10);
    if (!isNaN(seq)) {
      if (!unitsMap.has(seq)) unitsMap.set(seq, []);
      unitsMap.get(seq)!.push(row);
    }
  });

  const sortedSequences = Array.from(unitsMap.keys()).sort((a, b) => a - b);

  // Process Units (Aggregated)
  const units: UnitData[] = sortedSequences.map((seq) => {
    const unitRows = unitsMap.get(seq)!;

    // Aggregate Time: Average of all parts in the unit
    const totalDuration = unitRows.reduce((sum, r) => sum + (Number(r.first_cost_seconds) || 0), 0);
    const avgTimeSpent = unitRows.length > 0 ? totalDuration / unitRows.length : 0;

    // Aggregate Accuracy: Average of all parts
    const validAccRows = unitRows.filter(r => r.answer_right_rate != null);
    const totalAcc = validAccRows.reduce((sum, r) => sum + parseRate(r.answer_right_rate), 0);
    const accuracy = validAccRows.length > 0 ? totalAcc / validAccRows.length : 0;

    // Determine Status: If ANY part is '完课', we consider it High completion (Started/Active/Done)
    const isHigh = unitRows.some(r => r.unit_finish_status === '完课');

    let analysis = '';
    // Analysis Rules
    if (!isHigh) {
      analysis = '【知识版块】等你挑战';
    } else {
      if (accuracy >= CLASS_AVG_ACCURACY) {
        analysis = '掌握扎实，超越平均';
      } else {
        analysis = '态度认真，请巩固错题';
      }
    }

    return {
      unitNumber: seq,
      unitName: `第${seq}单元`,
      timeSpentSeconds: avgTimeSpent,
      status: isHigh ? 'high' : 'low',
      statusLabel: isHigh ? '已完课' : '待学习',
      accuracy,
      analysis
    };
  });

  // Calculate Aggregates
  const totalTimeSeconds = units.reduce((acc, u) => acc + u.timeSpentSeconds, 0); // Sum of unit averages
  // Note: Previous logic used studentRows sum. 
  // If we want "Cumulative Study Time", summing unit averages might be incorrect if units have varying number of lessons.
  // Requirement 2.1: "This semester cumulative study time".
  // Requirement 3.1: "Learning duration: take unit average learning duration".
  // "Learning duration use: first_cost_seconds".

  // To be safe and consistent with "first_cost_seconds is the source":
  // We calculate total time from raw rows (sum of first_cost_seconds of all lessons).
  const grandTotalTimeSeconds = studentRows.reduce((sum, r) => sum + (Number(r.first_cost_seconds) || 0), 0);

  // Average per session (using total rows as sessions)
  const avgTimePerSession = studentRows.length > 0 ? grandTotalTimeSeconds / studentRows.length : 0;

  const highCompletionCount = units.filter(u => u.status === 'high').length;
  const highUnits = units.filter(u => u.status === 'high');
  const avgAccuracy = highUnits.length > 0 
    ? highUnits.reduce((acc, u) => acc + u.accuracy, 0) / highUnits.length 
    : 0;

  // Generate Badges
  const completionBadge = getCompletionBadge(highCompletionCount);
  const accuracyBadge = getAccuracyBadge(avgAccuracy);

  // Generate Trend Analysis
  const trendAnalysis = analyzeTrend(units);

  // Generate Monthly Summary
  const highlights = units
    .filter(u => u.status === 'high' && u.accuracy >= CLASS_AVG_ACCURACY)
    .map(u => u.unitName);

  const improvements = units
    .filter(u => u.status === 'high' && u.accuracy < CLASS_AVG_ACCURACY)
    .map(u => u.unitName);

  const monthlySummary: MonthlySummary = {
    milestone: `本月你累计学习 ${toMinutes(grandTotalTimeSeconds)} 分钟，完成【${highCompletionCount}个知识点】相当于攻克了${highCompletionCount * 5}个高频易错点，扫清年级知识盲区。每一分钟，都在把薄弱变成强项。`,
    highlights: highlights.length > 0 ? [`【知识版块】表现突出，正确率持续领先，思路清晰。`] : [],
    improvements: improvements.length > 0 ? [`【知识版块】正确率暂时落后，建议加强读题训练与综合运用，随时和老师预约小灶课。`] : []
  };

  return {
    studentName: studentRows[0].real_name,
    grade: studentRows[0].package_grade,
    teacher: studentRows[0].counselor_name,
    totalTimeSeconds: grandTotalTimeSeconds,
    avgTimePerSession: avgTimePerSession,
    timeComment: `一节课${Math.ceil(avgTimePerSession/60)}分钟，短时高效，每天练出思维力！`,
    completionBadge,
    accuracyBadge,
    completedUnitsCount: highCompletionCount,
    units,
    trendAnalysis,
    monthlySummary
  };
};

const REQUIRED_COLUMNS = ['real_name', 'unit_sequence', 'unit_finish_status', 'answer_right_rate', 'first_cost_seconds'];

export const validateExcelData = (rows: any[]): { valid: boolean; error?: string } => {
  if (!rows || rows.length === 0) {
    return { valid: false, error: '文件为空或无法解析数据' };
  }
  const firstRow = rows[0];
  const missingColumns = REQUIRED_COLUMNS.filter(col => !(col in firstRow));
  if (missingColumns.length > 0) {
    return { valid: false, error: `缺少必要表头字段: ${missingColumns.join(', ')}。` };
  }
  return { valid: true };
};

export interface StudentSummary {
  name: string;
  grade: string;
  teacher: string;
  unitCount: number;
  lastUnit: string | number;
}

export const getStudentSummaries = (rows: StudentDataRow[]): StudentSummary[] => {
  const map = new Map<string, StudentSummary>();
  rows.forEach(row => {
    if (!row.real_name) return;
    if (!map.has(row.real_name)) {
      map.set(row.real_name, {
        name: row.real_name,
        grade: row.package_grade || '未知年级',
        teacher: row.counselor_name || '未知老师',
        unitCount: 0,
        lastUnit: 0
      });
    }
    const summary = map.get(row.real_name)!;

    // Count rows as records
    summary.unitCount += 1;

    if (row.unit_sequence && Number(row.unit_sequence) > Number(summary.lastUnit)) {
      summary.lastUnit = row.unit_sequence;
    }
  });
  return Array.from(map.values());
};

import React, { useCallback, useState } from 'react';
import * as XLSX from 'xlsx';
import { Upload, AlertCircle, FileText } from 'lucide-react';
import { StudentDataRow } from '../types';
import { validateExcelData } from '../utils';

interface Props {
  onDataLoaded: (data: StudentDataRow[]) => void;
}

const FileUpload: React.FC<Props> = ({ onDataLoaded }) => {
  const [error, setError] = useState<string | null>(null);
  const [dragActive, setDragActive] = useState(false);

  const processFile = (file: File) => {
    setError(null);
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const bstr = evt.target?.result;
        const wb = XLSX.read(bstr, { type: 'binary' });
        const wsname = wb.SheetNames[0];
        const ws = wb.Sheets[wsname];
        const data = XLSX.utils.sheet_to_json<StudentDataRow>(ws);

        const validation = validateExcelData(data);
        if (!validation.valid) {
          setError(validation.error || '文件格式无效');
          return;
        }

        onDataLoaded(data);
      } catch (err) {
        console.error(err);
        setError('解析文件时出错，请确保文件未损坏且格式正确。');
      }
    };
    reader.readAsBinaryString(file);
  };

  const handleFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) processFile(file);
  }, [onDataLoaded]);

  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      processFile(e.dataTransfer.files[0]);
    }
  }, [onDataLoaded]);

  return (
    <div className="max-w-xl mx-auto mt-20 font-sans">
      <div 
        className={`p-8 bg-white rounded-3xl shadow-xl border-4 border-dashed transition-all
          ${dragActive ? 'border-blue-400 bg-blue-50' : 'border-indigo-100'}
          ${error ? 'border-red-200 bg-red-50' : ''}`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
      >
        <div className="flex flex-col items-center gap-4 text-center">
          <div className={`p-5 rounded-full shadow-sm ${error ? 'bg-red-100' : 'bg-blue-100'}`}>
            {error ? (
              <AlertCircle className="w-10 h-10 text-red-500" />
            ) : (
              <Upload className="w-10 h-10 text-blue-500" />
            )}
          </div>

          <h2 className="text-2xl font-black text-indigo-900">
            {error ? 'Oops! 验证失败' : '上传学习数据 Excel'}
          </h2>

          <p className="text-gray-500 font-medium text-sm mb-2">
            请上传包含学生学习记录的 Excel 表格 (.xlsx, .xls)
          </p>

          {error && (
             <div className="bg-white border-2 border-red-100 text-red-500 font-bold text-sm p-4 rounded-xl w-full mb-2 shadow-sm">
               {error}
             </div>
          )}

          <label className="cursor-pointer bg-indigo-500 hover:bg-indigo-600 text-white font-bold px-8 py-3 rounded-full transition-all shadow-md transform hover:-translate-y-1 flex items-center gap-2">
            <FileText className="w-5 h-5" />
            <span>选择文件</span>
            <input 
              type="file" 
              accept=".xlsx, .xls" 
              className="hidden" 
              onChange={handleFileChange} 
            />
          </label>

          <div className="mt-8 text-left w-full bg-indigo-50/50 p-5 rounded-2xl border-2 border-indigo-50 text-xs text-indigo-400">
            <p className="font-bold mb-3 text-indigo-800 text-sm">必需表头字段:</p>
            <div className="grid grid-cols-2 gap-3 font-mono font-bold">
                <div className="bg-white px-2 py-1 rounded border border-indigo-100">real_name</div>
                <div className="bg-white px-2 py-1 rounded border border-indigo-100">unit_sequence</div>
                <div className="bg-white px-2 py-1 rounded border border-indigo-100">unit_finish_status</div>
                <div className="bg-white px-2 py-1 rounded border border-indigo-100">answer_right_rate</div>
                <div className="bg-white px-2 py-1 rounded border border-indigo-100">first_cost_seconds</div>
            </div>
            <p className="font-bold mt-4 mb-2 text-indigo-800 text-sm">可选字段:</p>
            <div className="font-mono flex gap-2 flex-wrap">
                <span className="bg-white px-2 py-1 rounded border border-indigo-100">package_grade</span>
                <span className="bg-white px-2 py-1 rounded border border-indigo-100">counselor_name</span>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

