const analyzeTrend = (units: UnitData[], classAvgAccuracy: number): TrendAnalysis => {
  if (units.length < 2) return { status: 'stable', title: '表现平稳', content: '数据较少，建议持续学习以积累更多数据。' };

  const validUnits = units.filter(u => u.status === 'high');
  if (validUnits.length < 2) return { status: 'growth', title: '蓄势待发', content: '完成课程较少，加油完成更多课程以解锁趋势分析！' };

  const accs = validUnits.map(u => u.accuracy);
  // Compare each unit against its specific class average
  const allAboveAvg = validUnits.every(u => u.accuracy >= u.classAccuracy);
  const allBelowAvg = validUnits.every(u => u.accuracy < u.classAccuracy);

  const first = accs[0];
  const last = accs[accs.length - 1];
  const slope = last - first;
  const isIncreasing = slope > 3; // meaningful increase

  // Rule 1: Always > Avg & Increasing
  if (allAboveAvg && isIncreasing) {
    return { status: 'excellent', title: '表现优秀且持续进步！', content: '单元的正确率均高于班级平均水平，并呈稳步上升趋势，展现扎实的掌握能力和良好的学习节奏。' };
  }
  // Rule 2: Always > Avg & Fluctuating (Not strict increasing)
  if (allAboveAvg) {
    return { status: 'stable_high', title: '整体表现稳定领先！', content: '虽然单元间略有波动，但全程均高于班级平均线，说明基础扎实，若能加强波动单元的巩固，表现将更出色。' };
  }

  // Get Class Avgs for first and last
  const firstClassAvg = validUnits[0].classAccuracy;
  const lastClassAvg = validUnits[validUnits.length - 1].classAccuracy;

  // Rule 3: Start < Avg, End > Avg (Improving)
  if (first < firstClassAvg && last > lastClassAvg) {
    return { status: 'catch_up', title: '进步显著，后劲十足！', content: '从前期稍显生疏到后期稳步超越班级平均，体现了良好的适应能力和反思改进的学习态度。' };
  }

  // Rule 4: Stable around Avg (check average distance from class avg line)
  const avgDist = validUnits.reduce((sum, u) => sum + Math.abs(u.accuracy - u.classAccuracy), 0) / validUnits.length;
  if (avgDist < 10) {
    return { status: 'stable_avg', title: '表现稳定，跟紧班级步伐', content: '各单元正确率与班级平均非常接近，若能进一步突破薄弱环节，有望实现领先。' };
  }
  // Rule 5: Always < Avg & Increasing
  if (allBelowAvg && isIncreasing) {
    return { status: 'improving', title: '虽暂未超越平均，但已步入上升通道！', content: '正确率逐单元提升，显示你正在逐步掌握方法，请保持当前学习节奏，加强复习。' };
  }

  // Fallback
  return { status: 'fluctuating', title: '学习状态略有波动', content: '正确率起伏较大，建议复习薄弱单元，找出知识盲区，争取下阶段稳步提升。' };
};

// --- Main Process Function ---

export const processExcelData = (
    rows: StudentDataRow[], 
    targetStudentName?: string,
    unitRange?: { min: number, max: number }
): ProcessedReportData | null => {
  if (!rows || rows.length === 0) return null;

  // 1. Calculate Global Class Averages Per Unit (using ALL data rows, grouped by level_sequence)
  const globalUnitStats = new Map<number, { totalAcc: number, count: number }>();

  rows.forEach(r => {
    // UPDATED: Use level_sequence as the Unit identifier
    const seq = parseInt(String(r.level_sequence), 10);
    // Ensure we parse the rate correctly
    const acc = parseRate(r.answer_right_rate);
    // Consider valid if sequence is number and we have a rate (even 0 is valid, but null/undefined/empty string is not)
    if (!isNaN(seq) && r.answer_right_rate != null && r.answer_right_rate !== '') {
        if (!globalUnitStats.has(seq)) globalUnitStats.set(seq, { totalAcc: 0, count: 0 });
        const entry = globalUnitStats.get(seq)!;
        entry.totalAcc += acc;
        entry.count += 1;
    }
  });

  const getClassAvgForUnit = (seq: number): number => {
      const entry = globalUnitStats.get(seq);
      if (!entry || entry.count === 0) return 85; // Fallback default if no data
      return entry.totalAcc / entry.count;
  };

  // 2. Filter for Target Student
  const primaryStudent = targetStudentName || rows[0].real_name;
  let studentRows = rows.filter(r => r.real_name === primaryStudent);

  if (studentRows.length === 0) return null;

  // 3. Apply Unit Range Filter (if provided)
  if (unitRange) {
      studentRows = studentRows.filter(r => {
          const seq = parseInt(String(r.level_sequence), 10);
          return !isNaN(seq) && seq >= unitRange.min && seq <= unitRange.max;
      });
      if (studentRows.length === 0) return null;
  }

  // Group by level_sequence (which is the "Unit" in the report)
  const unitsMap = new Map<number, StudentDataRow[]>();
  studentRows.forEach(row => {
    // UPDATED: Use level_sequence
    const seq = parseInt(String(row.level_sequence), 10);
    if (!isNaN(seq)) {
      if (!unitsMap.has(seq)) unitsMap.set(seq, []);
      unitsMap.get(seq)!.push(row);
    }
  });

  const sortedSequences = Array.from(unitsMap.keys()).sort((a, b) => a - b);

  // Process Units (Aggregated)
  const units: UnitData[] = sortedSequences.map((seq) => {
    const unitRows = unitsMap.get(seq)!;

    // Aggregate Time: Average of all parts in the unit
    // Filter out 0 duration rows for average calculation (first_cost_seconds > 0)
    const validTimeRows = unitRows.filter(r => parseSeconds(r.first_cost_seconds) > 0);
    const totalDuration = validTimeRows.reduce((sum, r) => sum + parseSeconds(r.first_cost_seconds), 0);
    const avgTimeSpent = validTimeRows.length > 0 ? totalDuration / validTimeRows.length : 0;

    // Aggregate Accuracy: Average of all parts
    const validAccRows = unitRows.filter(r => r.answer_right_rate != null);
    const totalAcc = validAccRows.reduce((sum, r) => sum + parseRate(r.answer_right_rate), 0);
    const accuracy = validAccRows.length > 0 ? totalAcc / validAccRows.length : 0;

    // Determine Status: If ANY part is '完课', we consider it High completion
    const isHigh = unitRows.some(r => r.unit_finish_status === '完课');

    // Get Class Average for this unit
    const classAvg = getClassAvgForUnit(seq);

    let analysis = '';
    // Analysis Rules
    if (!isHigh) {
      analysis = '【知识版块】等你挑战';
    } else {
      if (accuracy >= classAvg) {
        analysis = '掌握扎实，超越平均';
      } else {
        analysis = '态度认真，请巩固错题';
      }
    }

    return {
      unitNumber: seq,
      unitName: `第${seq}单元`,
      timeSpentSeconds: avgTimeSpent,
      status: isHigh ? 'high' : 'low',
      statusLabel: isHigh ? '已完课' : '待学习',
      accuracy,
      classAccuracy: classAvg,
      analysis
    };
  });

  // Calculate Aggregates
  // Grand Total Time: Sum of all rows for the student (filter > 0)
  const validGlobalTimeRows = studentRows.filter(r => parseSeconds(r.first_cost_seconds) > 0);
  const grandTotalTimeSeconds = validGlobalTimeRows.reduce((sum, r) => sum + parseSeconds(r.first_cost_seconds), 0);

  // Average per session (using total VALID rows as sessions)
  const avgTimePerSession = validGlobalTimeRows.length > 0 ? grandTotalTimeSeconds / validGlobalTimeRows.length : 0;

  const highCompletionCount = units.filter(u => u.status === 'high').length;
  const highUnits = units.filter(u => u.status === 'high');
  const avgAccuracy = highUnits.length > 0 
    ? highUnits.reduce((acc, u) => acc + u.accuracy, 0) / highUnits.length 
    : 0;

  // Generate Badges
  const completionBadge = getCompletionBadge(highCompletionCount);
  const accuracyBadge = getAccuracyBadge(avgAccuracy);

  // Generate Trend Analysis
  const trendAnalysis = analyzeTrend(units, 85);

  // Generate Monthly Summary
  const highlights = units
    .filter(u => u.status === 'high' && u.accuracy >= u.classAccuracy)
    .map(u => u.unitName);

  const improvements = units
    .filter(u => u.status === 'high' && u.accuracy < u.classAccuracy)
    .map(u => u.unitName);

  const monthlySummary: MonthlySummary = {
    milestone: `本月你累计学习 ${toMinutes(grandTotalTimeSeconds)} 分钟，完成【${highCompletionCount}个知识点】相当于攻克了${highCompletionCount * 5}个高频易错点，扫清年级知识盲区。每一分钟，都在把薄弱变成强项。`,
    highlights: highlights.length > 0 ? [`【知识版块】表现突出，正确率持续领先，思路清晰。`] : [],
    improvements: improvements.length > 0 ? [`【知识版块】正确率暂时落后，建议加强读题训练与综合运用，随时和老师预约小灶课。`] : []
  };

  return {
    studentName: studentRows[0].real_name,
    grade: studentRows[0].package_grade,
    teacher: studentRows[0].counselor_name,
    totalTimeSeconds: grandTotalTimeSeconds,
    avgTimePerSession: avgTimePerSession,
    timeComment: `一节课${Math.ceil(avgTimePerSession/60)}分钟，短时高效，每天练出思维力！`,
    completionBadge,
    accuracyBadge,
    completedUnitsCount: highCompletionCount,
    units,
    trendAnalysis,
    monthlySummary
  };
};

