import React, { useState } from 'react';
import FileUpload from './components/FileUpload';
import ReportView from './components/ReportView';
import StudentList from './components/StudentList';
import { StudentDataRow, ProcessedReportData } from './types';
import { processExcelData, getAvailableUnits } from './utils';

type AppView = 'upload' | 'list' | 'report';

function App() {
  const [view, setView] = useState<AppView>('upload');
  const [rawData, setRawData] = useState<StudentDataRow[]>([]);
  const [reportData, setReportData] = useState<ProcessedReportData | null>(null);

  // State for Filtering
  const [selectedStudentName, setSelectedStudentName] = useState<string | null>(null);
  const [availableUnits, setAvailableUnits] = useState<number[]>([]);
  const [unitRange, setUnitRange] = useState<{ min: number, max: number }>({ min: 1, max: 1 });

  const handleDataLoaded = (data: StudentDataRow[]) => {
    setRawData(data);
    setView('list');
  };

  const handleSelectStudent = (studentName: string) => {
    // 1. Calculate available units for this student first
    const units = getAvailableUnits(rawData, studentName);

    if (units.length === 0) {
        alert('该学生没有有效的单元数据');
        return;
    }

    const min = units[0];
    const max = units[units.length - 1];

    setAvailableUnits(units);
    setUnitRange({ min, max });
    setSelectedStudentName(studentName);

    // 2. Process data with the full range initially
    const processed = processExcelData(rawData, studentName, { min, max });
    if (processed) {
      setReportData(processed);
      setView('report');
    } else {
      alert('生成报告失败，请重试');
    }
  };

  const handleUnitRangeChange = (min: number, max: number) => {
    if (!selectedStudentName) return;

    setUnitRange({ min, max });
    const processed = processExcelData(rawData, selectedStudentName, { min, max });
    if (processed) {
      setReportData(processed);
    }
  };

  const handleReset = () => {
    setRawData([]);
    setReportData(null);
    setSelectedStudentName(null);
    setAvailableUnits([]);
    setView('upload');
  };

  const handleBackToList = () => {
    setReportData(null);
    setSelectedStudentName(null);
    setView('list');
  };

  return (
    <div className="min-h-screen pb-10 bg-blue-50 font-sans">
      <header className="bg-white border-b-4 border-blue-100 py-4 mb-8 shadow-sm">
        <div className="container mx-auto px-4">
            <h1 className="text-2xl font-black text-indigo-600 flex items-center gap-2 cursor-pointer" onClick={() => view !== 'upload' && handleBackToList()}>
                🎓 学习情况报告生成器
            </h1>
        </div>
      </header>

      <main className="container mx-auto px-4">
        {view === 'upload' && (
          <FileUpload onDataLoaded={handleDataLoaded} />
        )}

        {view === 'list' && (
          <StudentList 
            data={rawData} 
            onSelectStudent={handleSelectStudent} 
            onReupload={handleReset}
          />
        )}

        {view === 'report' && reportData && (
          <ReportView 
            data={reportData} 
            onReset={handleReset} 
            onBack={handleBackToList}
            availableUnits={availableUnits}
            currentRange={unitRange}
            onRangeChange={handleUnitRangeChange}
          />
        )}
      </main>
    </div>
  );
}

export default App;

