import React from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { UnitData } from '../types';

interface Props {
  data: UnitData[];
}

const ReportChart: React.FC<Props> = ({ data }) => {
  const chartData = data.map(d => ({
    name: d.unitNumber,
    fullName: d.unitName,
    accuracy: d.status === 'high' ? d.accuracy : null,
    // Use the dynamic class accuracy calculated from the whole dataset for this unit
    classAverage: d.classAccuracy 
  }));

  return (
    <div className="w-full h-full flex flex-col font-sans">
      <div className="flex-grow min-h-0">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={chartData}
            margin={{ top: 20, right: 30, left: 0, bottom: 20 }}
          >
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#fed7aa" />
            <XAxis 
              dataKey="name" 
              tick={{fontSize: 14, fill: '#9a3412', fontWeight: 700}} 
              axisLine={false}
              tickLine={false}
              label={{ value: '单元', position: 'insideBottomRight', offset: -10, fontSize: 12, fill: '#fdba74' }}
              padding={{ left: 20, right: 20 }}
            />
            <YAxis 
              domain={[0, 100]} 
              tick={{fontSize: 12, fill: '#9a3412', fontWeight: 600}}
              axisLine={false}
              tickLine={false}
              width={35}
            />
            <Tooltip 
              formatter={(value: number, name: string) => [
                `${value.toFixed(1)}%`, 
                name === 'accuracy' ? '我的正确率' : '班级平均'
              ]}
              labelFormatter={(label) => `第${label}单元`}
              contentStyle={{ 
                  borderRadius: '16px', 
                  border: '2px solid #fdba74', 
                  boxShadow: '0 4px 12px rgba(251, 146, 60, 0.2)',
                  fontFamily: 'Nunito, sans-serif'
              }}
              cursor={{ stroke: '#fdba74', strokeWidth: 2, strokeDasharray: '4 4' }}
            />

            {/* Class Average Line - Now dynamic per point */}
            <Line 
              type="monotone" 
              dataKey="classAverage" 
              name="classAverage" 
              stroke="#cbd5e1" 
              strokeWidth={3}
              strokeDasharray="8 8" 
              dot={{ r: 4, fill: '#cbd5e1', strokeWidth: 0 }} 
              activeDot={false}
            />

            {/* Student Line */}
            <Line
              connectNulls
              type="monotone"
              dataKey="accuracy"
              name="accuracy"
              stroke="#f97316" 
              strokeWidth={4}
              dot={{ r: 6, fill: '#fff', stroke: '#f97316', strokeWidth: 3 }}
              activeDot={{ r: 8, fill: '#f97316', stroke: '#fff', strokeWidth: 2 }}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>

      <div className="flex justify-center gap-6 text-sm font-bold mt-2 pb-1">
        <div className="flex items-center gap-2">
            <span className="w-3 h-3 rounded-full border-4 border-orange-500 bg-white"></span>
            <span className="text-orange-700">我的正确率</span>
        </div>
        <div className="flex items-center gap-2">
            <span className="w-6 h-1 bg-slate-400 border-t-2 border-dashed border-slate-300"></span>
            <span className="text-slate-500">班级平均 (动态)</span>
        </div>
      </div>
    </div>
  );
};

