  ArrowLeft, 
  Filter,
  Download,
  User,
  Trophy,
  Target,
  BarChart2,
  Lightbulb,
  Clock,
  BookOpen,
  Star
} from 'lucide-react';

interface Props {
  data: ProcessedReportData;
  onReset: () => void;
  onBack?: () => void;

  availableUnits?: number[];
  currentRange?: { min: number, max: number };
  onRangeChange?: (min: number, max: number) => void;
}

const ReportView: React.FC<Props> = ({ 
    data, 
    onReset, 
    onBack, 
    availableUnits = [], 
    currentRange, 
    onRangeChange 
}) => {
  const reportRef = useRef<HTMLDivElement>(null);

  const handleStartChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (!currentRange || !onRangeChange) return;
      const val = parseInt(e.target.value);
      onRangeChange(val, val > currentRange.max ? val : currentRange.max);
  };

  const handleEndChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (!currentRange || !onRangeChange) return;
      const val = parseInt(e.target.value);
      onRangeChange(val < currentRange.min ? val : currentRange.min, val);
  };

  const getTitle = () => {
      if (currentRange) {
          return `${data.studentName} ${currentRange.min}-${currentRange.max}单元学习成长记录`;
      }
      return `${data.studentName} 学习成长记录`;
