const analyzeTrend = (units: UnitData[], classAvgAccuracy: number): TrendAnalysis => {
  if (units.length < 2) return { status: 'stable', title: '表现平稳', content: '数据较少，建议持续学习以积累更多数据。' };

  const validUnits = units.filter(u => u.status === 'high');
  if (validUnits.length < 2) return { status: 'growth', title: '蓄势待发', content: '完成课程较少，加油完成更多课程以解锁趋势分析！' };

  const accs = validUnits.map(u => u.accuracy);
  // Compare each unit against its specific class average
  const allAboveAvg = validUnits.every(u => u.accuracy >= u.classAccuracy);
  const allBelowAvg = validUnits.every(u => u.accuracy < u.classAccuracy);

  const first = accs[0];
  const last = accs[accs.length - 1];
  const slope = last - first;
  const isIncreasing = slope > 3; // meaningful increase

  // Rule 1: Always > Avg & Increasing
  if (allAboveAvg && isIncreasing) {
    return { status: 'excellent', title: '表现优秀且持续进步！', content: '单元的正确率均高于班级平均水平，并呈稳步上升趋势，展现扎实的掌握能力和良好的学习节奏。' };
  }
  // Rule 2: Always > Avg & Fluctuating (Not strict increasing)
  if (allAboveAvg) {
    return { status: 'stable_high', title: '整体表现稳定领先！', content: '虽然单元间略有波动，但全程均高于班级平均线，说明基础扎实，若能加强波动单元的巩固，表现将更出色。' };
  }

  // Get Class Avgs for first and last
  const firstClassAvg = validUnits[0].classAccuracy;
  const lastClassAvg = validUnits[validUnits.length - 1].classAccuracy;

  // Rule 3: Start < Avg, End > Avg (Improving)
  if (first < firstClassAvg && last > lastClassAvg) {
    return { status: 'catch_up', title: '进步显著，后劲十足！', content: '从前期稍显生疏到后期稳步超越班级平均，体现了良好的适应能力和反思改进的学习态度。' };
  }

  // Rule 4: Stable around Avg (check average distance from class avg line)
  const avgDist = validUnits.reduce((sum, u) => sum + Math.abs(u.accuracy - u.classAccuracy), 0) / validUnits.length;
  if (avgDist < 10) {
    return { status: 'stable_avg', title: '表现稳定，跟紧班级步伐', content: '各单元正确率与班级平均非常接近，若能进一步突破薄弱环节，有望实现领先。' };
  }
  // Rule 5: Always < Avg & Increasing
  if (allBelowAvg && isIncreasing) {
    return { status: 'improving', title: '虽暂未超越平均，但已步入上升通道！', content: '正确率逐单元提升，显示你正在逐步掌握方法，请保持当前学习节奏，加强复习。' };
  }

  // Fallback
  return { status: 'fluctuating', title: '学习状态略有波动', content: '正确率起伏较大，建议复习薄弱单元，找出知识盲区，争取下阶段稳步提升。' };
};

// --- Main Process Function ---

export const processExcelData = (
    rows: StudentDataRow[], 
    targetStudentName?: string,
    unitRange?: { min: number, max: number }
): ProcessedReportData | null => {
  if (!rows || rows.length === 0) return null;

  // 1. Calculate Global Class Averages Per Unit (using ALL data rows, grouped by level_sequence)
  const globalUnitStats = new Map<number, { totalAcc: number, count: number }>();

  rows.forEach(r => {
    const seq = parseInt(String(r.level_sequence), 10);
    const acc = parseRate(r.answer_right_rate);

    // Consider valid if sequence is number and we have a rate
    if (!isNaN(seq) && r.answer_right_rate != null && r.answer_right_rate !== '') {
        if (!globalUnitStats.has(seq)) globalUnitStats.set(seq, { totalAcc: 0, count: 0 });
        const entry = globalUnitStats.get(seq)!;
        entry.totalAcc += acc;
        entry.count += 1;
    }
  });

  const getClassAverageForUnit = (unitNum: number): number => {
      const stats = globalUnitStats.get(unitNum);
      if (!stats || stats.count === 0) return 0;
      return stats.totalAcc / stats.count;
  };

  // 2. Filter for Target Student
  if (!targetStudentName) return null;
  const studentRows = rows.filter(r => r.real_name === targetStudentName);
  if (studentRows.length === 0) return null;

  // 3. Group by Unit (level_sequence)
  const unitMap = new Map<number, { 
    name: string, 
    totalSeconds: number, 
    accuracies: number[], 
    status: string,
    rows: StudentDataRow[] 
  }>();

  studentRows.forEach(r => {
    const unitNum = parseInt(String(r.level_sequence), 10);
    if (isNaN(unitNum)) return;

    // Filter by Range if provided
    if (unitRange && (unitNum < unitRange.min || unitNum > unitRange.max)) return;

    if (!unitMap.has(unitNum)) {
      unitMap.set(unitNum, { name: `第${unitNum}单元`, totalSeconds: 0, accuracies: [], status: 'low', rows: [] });
    }
    const u = unitMap.get(unitNum)!;

    u.totalSeconds += parseSeconds(r.first_cost_seconds);
    const rate = parseRate(r.answer_right_rate);
    if (rate > 0 || r.answer_right_rate === '0') u.accuracies.push(rate);
    if (r.unit_finish_status === '完课') u.status = 'high';
    u.rows.push(r);
  });

  // 4. Transform to UnitData
  const units: UnitData[] = Array.from(unitMap.entries()).map(([num, data]) => {
    const avgAcc = data.accuracies.length > 0 
      ? data.accuracies.reduce((a, b) => a + b, 0) / data.accuracies.length 
      : 0;

    // Dynamic Class Average for this specific unit
    const classAvg = getClassAverageForUnit(num);

    // Generate specific analysis
    let analysis = '';
    if (data.status === 'high') {
        if (avgAcc >= 90) analysis = '掌握极佳！';
        else if (avgAcc >= classAvg) analysis = '超越平均，表现不错。';
        else if (avgAcc >= 60) analysis = '基础达标，仍有提升空间。';
        else analysis = '建议复习，巩固基础。';
    } else {
        analysis = '未完课，请继续加油！';
    }

    return {
      unitNumber: num,
      unitName: data.name,
      timeSpentSeconds: data.totalSeconds,
      status: data.status as 'high' | 'low',
      statusLabel: data.status === 'high' ? '已完课' : '学习中',
      accuracy: avgAcc,
      classAccuracy: classAvg,
      analysis
    };
  }).sort((a, b) => a.unitNumber - b.unitNumber);

  // 5. Aggregates
  const totalSeconds = units.reduce((sum, u) => sum + u.timeSpentSeconds, 0);
  const avgTime = units.length > 0 ? totalSeconds / units.length : 0;

  // Time comment
  const avgMins = toMinutes(avgTime);
  let timeComment = '';
  if (avgMins > 45) timeComment = '你非常刻苦，投入了大量时间，';
  else if (avgMins > 20) timeComment = '你的学习节奏控制得很棒，';
  else timeComment = '你反应敏捷，学习效率很高，';

  // Badges
  const highStatusCount = units.filter(u => u.status === 'high').length;
  const overallAvgAcc = units.length > 0 
    ? units.reduce((sum, u) => sum + u.accuracy, 0) / units.length 
    : 0;

  const completionBadge = getCompletionBadge(highStatusCount);
  const accuracyBadge = getAccuracyBadge(overallAvgAcc);

  // Trend
  const trendAnalysis = analyzeTrend(units, 0); // Class Avg is handled per unit now

  // Monthly Summary
  const improvements = units
    .filter(u => u.status === 'high' && u.accuracy < 60)
    .map(u => u.unitName);

  const monthlySummary: MonthlySummary = {
    milestone: `本阶段共学习${units.length}个单元，${highStatusCount}个单元完美通关！`,
    highlights: [],
    improvements
  };

  // Get raw grade from first row
  const rawGrade = studentRows[0]?.package_grade || '';

  return {
    studentName: targetStudentName,
    grade: translateGrade(rawGrade), // Use helper here
    teacher: studentRows[0]?.counselor_name || '未知老师',
    totalTimeSeconds: totalSeconds,
    avgTimePerSession: avgTime,
    timeComment,
    completionBadge,
    accuracyBadge,
    completedUnitsCount: highStatusCount,
    units,
    trendAnalysis,
    monthlySummary
  };
};

export interface StudentSummary {
  name: string;
  grade: string;
  teacher: string;
  unitCount: number;
  lastUnit: number;
}

export const getStudentSummaries = (rows: StudentDataRow[]): StudentSummary[] => {
  const map = new Map<string, StudentSummary>();

  rows.forEach(r => {
    if (!map.has(r.real_name)) {
      map.set(r.real_name, {
        name: r.real_name,
        grade: translateGrade(r.package_grade), // Use helper here
        teacher: r.counselor_name,
        unitCount: 0,
        lastUnit: 0
      });
    }
    const s = map.get(r.real_name)!;

    // Update simple stats
    const seq = parseInt(String(r.level_sequence), 10);
    if (!isNaN(seq)) {
        s.lastUnit = Math.max(s.lastUnit, seq);
        // This is a rough count of rows, not unique units, but suffices for list view "record count"
        s.unitCount++; 
    }
  });

  return Array.from(map.values());
};

