export const formatDuration = (seconds: number): string => {
  if (!seconds || isNaN(seconds)) return '0分钟';
  const hours = Math.floor(seconds / 3600);
  const remainingSeconds = seconds % 3600;
  const mins = Math.ceil(remainingSeconds / 60); // Round up for "minutes"

  if (hours > 0) {
    return `${hours}小时${mins > 0 ? ` ${mins}分钟` : ''}`;
  }
  return `${mins}分钟`;
};

// Simple helper for "X minutes" format used in summaries
const toMinutes = (seconds: number): number => Math.ceil(seconds / 60);

export const parseRate = (rate: string | number): number => {
  if (typeof rate === 'number') return rate * 100;
  if (typeof rate === 'string') {
    if (rate.includes('%')) {
      return parseFloat(rate.replace('%', ''));
    }
    const val = parseFloat(rate);
    return val <= 1 ? val * 100 : val;
  }
  return 0;
};

export const parseSeconds = (val: string | number): number => {
  if (typeof val === 'number') return val;
  if (!val) return 0;
  const str = String(val).trim();

  // Handle Chinese "X分X秒" format
  if (str.includes('分') || str.includes('秒')) {
    let totalSeconds = 0;
    const minutesMatch = str.match(/(\d+)\s*分/);
    const secondsMatch = str.match(/(\d+)\s*秒/);

    if (minutesMatch) {
      totalSeconds += parseInt(minutesMatch[1], 10) * 60;
    }
    if (secondsMatch) {
      totalSeconds += parseInt(secondsMatch[1], 10);
    }
    return totalSeconds;
  }

  // Fallback for standard numeric strings
  const num = parseFloat(str);
  return isNaN(num) ? 0 : num;
};

// --- Helper: Grade Translation ---
const translateGrade = (grade: string): string => {
  if (!grade) return '未知年级';
  const map: Record<string, string> = {
    'pk': '幼儿园小班',
    'k': '幼儿园大班',
    'one': '一年级',
    'two': '二年级',
    'three': '三年级',
    'four': '四年级',
    'five': '五年级',
    'six': '六年级',
    'seven': '七年级',
    'eight': '八年级',
    'nine': '九年级'
  };

  const lowerGrade = grade.toLowerCase().trim();
  // Check exact match
  if (map[lowerGrade]) return map[lowerGrade];

  // Check if it contains the key (e.g. "Grade One")
  const foundKey = Object.keys(map).find(k => lowerGrade.includes(k));
  return foundKey ? map[foundKey] : grade;
};

// --- Helper: Get Available Units for Student ---
export const getAvailableUnits = (rows: StudentDataRow[], studentName: string): number[] => {
    const units = new Set<number>();
    rows.forEach(r => {
        if (r.real_name === studentName) {
            const seq = parseInt(String(r.level_sequence), 10);
            if (!isNaN(seq)) {
                units.add(seq);
            }
        }
    });
    return Array.from(units).sort((a, b) => a - b);
};

// --- Helper: Validate Excel Data ---
export const validateExcelData = (data: any[]): { valid: boolean; error?: string } => {
  if (!data || data.length === 0) {
    return { valid: false, error: '文件为空或无法解析数据' };
  }

  // Check the first row for required fields
  const firstRow = data[0];
  const strictRequiredFields = [
      'real_name',
      'level_sequence',
      'unit_sequence',
      'unit_finish_status',
      'answer_right_rate',
      'first_cost_seconds'
  ];

  const missingFields = strictRequiredFields.filter(field => !(field in firstRow));

  if (missingFields.length > 0) {
    return { 
      valid: false, 
      error: `缺少必要字段: ${missingFields.join(', ')}。请确保上传的Excel包含正确的表头。` 
    };
  }

  return { valid: true };
};

