            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e7e5e4" />
            <XAxis 
              dataKey="name" 
              tick={{fontSize: 14, fill: '#78716c', fontWeight: 800}} // Stone-500
              axisLine={false}
              tickLine={false}
              label={{ value: '单元', position: 'insideBottomRight', offset: -10, fontSize: 12, fill: '#a8a29e', fontWeight: 700 }}
              padding={{ left: 20, right: 20 }}
            />
            <YAxis 
              domain={[0, 100]} 
              tick={{fontSize: 12, fill: '#78716c', fontWeight: 700}}
              axisLine={false}
              tickLine={false}
              width={35}
            />
            <Tooltip 
              formatter={(value: number, name: string) => [
                `${value.toFixed(1)}%`, 
                name === 'accuracy' ? '我的成绩' : '班级平均'
              ]}
              labelFormatter={(label) => `第${label}单元`}
              contentStyle={{ 
                  borderRadius: '16px', 
                  border: `2px solid ${color}`, // Dynamic Border
                  backgroundColor: '#fff',
                  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                  fontFamily: 'Nunito, sans-serif',
                  color: '#44403c', // Stone-700
                  fontWeight: 'bold'
              }}
              cursor={{ stroke: color, strokeWidth: 2, strokeDasharray: '4 4' }}
            />

            {/* Class Average Line - Muted Blue */}
            <Line 
              type="monotone" 
              dataKey="classAverage" 
              name="classAverage" 
              stroke="#cbd5e1" // Slate-300
              strokeWidth={4}
              strokeDasharray="8 8" 
              dot={{ r: 0 }} 
              activeDot={false}
            />

            {/* Student Line - Dynamic Color */}
            <Line
              connectNulls
              type="monotone"
              dataKey="accuracy"
              name="accuracy"
              stroke={color} 
              strokeWidth={5}
              dot={{ r: 6, fill: '#fff', stroke: color, strokeWidth: 4 }}
              activeDot={{ r: 9, fill: color, stroke: '#fff', strokeWidth: 3 }}
            />
          </LineChart>
        </ResponsiveContainer>
      </div>

    </div>
  );
};

