// --- Component ---

interface Props {
  data: ProcessedReportData;
  onReset: () => void;
  onBack?: () => void;

  availableUnits?: number[];
  currentRange?: { min: number, max: number };
  onRangeChange?: (min: number, max: number) => void;

  currentTheme: ThemeType;
  onThemeChange: (theme: ThemeType) => void;
}

const ReportView: React.FC<Props> = ({ 
    data, 
    onReset, 
    onBack, 
    availableUnits = [], 
    currentRange, 
    onRangeChange,
    currentTheme,
    onThemeChange
}) => {
  const reportRef = useRef<HTMLDivElement>(null);

  // Get active theme colors
  const t = themes[currentTheme].colors;

  const handleStartChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (!currentRange || !onRangeChange) return;
      const val = parseInt(e.target.value);
      onRangeChange(val, val > currentRange.max ? val : currentRange.max);
  };

  const handleEndChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      if (!currentRange || !onRangeChange) return;
      const val = parseInt(e.target.value);
      onRangeChange(val < currentRange.min ? val : currentRange.min, val);
  };

  const getTitle = () => {
      if (currentRange) {
          return `${data.studentName} ${currentRange.min}-${currentRange.max}单元学习成长记录`;
      }
      return `${data.studentName} 学习成长记录`;
  };

  return (
    <div className="max-w-6xl mx-auto my-6 font-sans text-stone-700">

      {/* Control Bar */}
      <div className="mb-6 flex flex-col md:flex-row justify-between items-center print:hidden px-4 gap-4">

        {/* Left Controls: Back / Reset / Print */}
        <div className="flex items-center gap-3">
             {onBack && (
              <button 
                onClick={onBack}
                className="flex items-center gap-2 bg-white px-5 py-2.5 rounded-full border-2 border-slate-100 shadow-sm text-slate-600 hover:bg-slate-50 font-bold transition-transform hover:scale-105"
              >
                <ArrowLeft className="w-5 h-5" />
                返回
              </button>
            )}
            <button 
                onClick={onReset}
                className={`text-sm font-bold bg-white px-5 py-2.5 rounded-full border-2 shadow-sm transition-colors ${t.btnSecondary}`}
            >
                重新上传
            </button>
            <button 
                onClick={() => window.print()}
                className={`flex items-center gap-2 text-white text-sm font-bold px-6 py-2.5 rounded-full active:shadow-none active:translate-y-1 transition-all ${t.btnPrimary}`}
            >
                <Download className="w-5 h-5" />
                保存/打印
            </button>
        </div>

        {/* Middle/Right Controls: Theme & Filter */}
        <div className="flex flex-wrap items-center gap-3">

            {/* Theme Switcher */}
            <div className="flex items-center gap-1 bg-white p-1 rounded-full border-2 border-slate-100 shadow-sm">
                <div className="px-2 flex items-center text-slate-400">
                    <Palette className="w-4 h-4" />
                </div>
                {(Object.keys(themes) as ThemeType[]).map((key) => {
                    const theme = themes[key];
                    const isActive = currentTheme === key;
                    return (
                        <button
                            key={key}
                            onClick={() => onThemeChange(key)}
                            className={`flex items-center gap-1 px-3 py-1.5 rounded-full text-xs font-bold transition-all ${
                                isActive 
                                ? 'bg-slate-800 text-white shadow-md' 
                                : 'text-slate-500 hover:bg-slate-100'
                            }`}
                        >
                            {theme.icon}
                            {theme.label}
                        </button>
                    )
                })}
            </div>

            {/* Range Filter */}
            {currentRange && availableUnits.length > 0 && (
                <div className="flex items-center gap-2 bg-white px-4 py-2 rounded-full border-2 border-slate-100 shadow-sm">
                    <div className="flex items-center gap-2 text-slate-400 font-bold mr-2">
                        <Filter className="w-5 h-5" />
                        <span className="text-sm">范围</span>
                    </div>
                    <select 
                        value={currentRange.min} 
                        onChange={handleStartChange}
                        className="bg-slate-50 border-2 border-slate-100 rounded-lg px-2 py-1 text-sm font-bold text-slate-700 outline-none cursor-pointer hover:border-slate-300 transition-colors"
                    >
                        {availableUnits.map(u => <option key={u} value={u}>第 {u} 单元</option>)}
                    </select>
                    <span className="text-slate-300 font-black">→</span>
                    <select 
                        value={currentRange.max} 
                        onChange={handleEndChange}
                        className="bg-slate-50 border-2 border-slate-100 rounded-lg px-2 py-1 text-sm font-bold text-slate-700 outline-none cursor-pointer hover:border-slate-300 transition-colors"
                    >
                        {availableUnits.map(u => <option key={u} value={u}>第 {u} 单元</option>)}
                    </select>
                </div>
            )}
        </div>
