                <div className="flex items-center gap-3 mb-6">
                    <div className={`w-12 h-12 ${t.profileIconBg} rounded-full flex items-center justify-center ${t.profileIconText} border-4 border-white shadow-sm`}>
                        <User className="w-7 h-7" />
                    </div>
                    <h3 className={`font-black text-xl ${t.profileIconText}`}>我的档案</h3>
