                    <div className={`flex items-center justify-between border-b pb-2 ${t.profileBorder}`}>
                        <span className="text-sm font-bold opacity-60">姓名</span>
                        <span className="text-xl font-black text-stone-700">{data.studentName}</span>
                    </div>
                    <div className={`flex items-center justify-between border-b pb-2 ${t.profileBorder}`}>
                        <span className="text-sm font-bold opacity-60">年级</span>
                        <span className="font-bold text-stone-600 bg-white px-3 py-1 rounded-lg text-sm border border-stone-100">{data.grade}</span>
                    </div>
                    <div className="flex items-center justify-between">
                        <span className="text-sm font-bold opacity-60">辅导老师</span>
                        <span className="font-bold text-stone-600">{data.teacher}</span>
                    </div>
                </div>
            </div>

            {/* Right: Overall Performance */}
            <div className={`w-full md:w-2/3 ${t.badgesBg} p-6 relative overflow-hidden`}>
                {/* Background Decoration */}
                <div className={`absolute top-[-20px] right-[-20px] w-32 h-32 ${t.badgesDecoration} rounded-full opacity-50 z-0`}></div>

                <div className="relative z-10">
                    <div className="flex items-center gap-2 mb-2">
