        </div>

        {/* SECTION 2: Bottom Grid */}
        <div className="flex flex-col lg:flex-row min-h-[500px]">

            {/* Left Column: Stats & Table */}
            <div className={`w-full lg:w-3/5 border-b-4 lg:border-b-0 lg:border-r-4 ${t.containerBorder} flex flex-col bg-white`}>
