                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>

                {/* Ranking Footer Banner */}
                {currentStudentRankInfo && (
                    <div className={`${c.rankingBannerBg} ${c.rankingBannerText} p-4 text-center text-sm font-bold flex items-center justify-center gap-2`}>
