// --- Ranking Logic ---

interface RankingItem {
  name: string;
  userId: string | number;
  avgAccuracy: number;
  rank: number;
}

const calculateRankings = (
    allRows: StudentDataRow[], 
    range: { min: number, max: number }
): { rankings: RankingItem[], totalStudents: number } => {
    // Group by student
    const studentMap = new Map<string, { userId: string | number, totalRate: number, count: number }>();

    allRows.forEach(row => {
        const seq = parseInt(String(row.level_sequence), 10);
        // Only include units in range
        if (isNaN(seq) || seq < range.min || seq > range.max) return;

        const rate = parseRate(row.answer_right_rate);

        if (!studentMap.has(row.real_name)) {
            studentMap.set(row.real_name, { userId: row.user_id, totalRate: 0, count: 0 });
        }

        const entry = studentMap.get(row.real_name)!;
        entry.totalRate += rate;
        entry.count += 1;
    });

    const results: RankingItem[] = [];
    studentMap.forEach((val, name) => {
        if (val.count > 0) {
            results.push({
                name,
                userId: val.userId,
                avgAccuracy: val.totalRate / val.count,
                rank: 0 // placeholder
            });
        }
    });

    // Sort Descending
    results.sort((a, b) => b.avgAccuracy - a.avgAccuracy);

    // Assign Rank (Handle ties? Simple index for now)
    results.forEach((item, index) => {
        item.rank = index + 1;
    });

    return { rankings: results, totalStudents: results.length };
};


