export const formatDuration = (seconds: number): string => {
  if (!seconds || isNaN(seconds)) return '0分钟';
  const hours = Math.floor(seconds / 3600);
  const remainingSeconds = seconds % 3600;
  const mins = Math.ceil(remainingSeconds / 60);

  if (hours > 0) {
    return `${hours}小时${mins > 0 ? ` ${mins}分钟` : ''}`;
  }
  return `${mins}分钟`;
};

export const parseRate = (rate: string | number): number => {
  if (typeof rate === 'number') return rate * 100;
  if (typeof rate === 'string') {
    if (rate.includes('%')) return parseFloat(rate.replace('%', ''));
    const val = parseFloat(rate);
    return val <= 1 ? val * 100 : val;
  }
  return 0;
};

export const parseSeconds = (val: string | number): number => {
  if (typeof val === 'number') return val;
  if (!val) return 0;
  const str = String(val).trim();
  if (str.includes('分') || str.includes('秒')) {
    let totalSeconds = 0;
    const minutesMatch = str.match(/(\d+)\s*分/);
    const secondsMatch = str.match(/(\d+)\s*秒/);
    if (minutesMatch) totalSeconds += parseInt(minutesMatch[1], 10) * 60;
    if (secondsMatch) totalSeconds += parseInt(secondsMatch[1], 10);
    return totalSeconds;
  }
  const num = parseFloat(str);
  return isNaN(num) ? 0 : num;
};

const translateGrade = (grade: string): string => {
  if (!grade) return '未知年级';
  const map: Record<string, string> = {
    'pk': '幼儿园小班', 'k': '幼儿园大班', 'one': '一年级', 'two': '二年级',
    'three': '三年级', 'four': '四年级', 'five': '五年级', 'six': '六年级'
  };
  const lowerGrade = grade.toLowerCase().trim();
  if (map[lowerGrade]) return map[lowerGrade];
  const foundKey = Object.keys(map).find(k => lowerGrade.includes(k));
  return foundKey ? map[foundKey] : grade;
};

export const getAvailableUnits = (rows: StudentDataRow[], studentName: string): number[] => {
    const units = new Set<number>();
    rows.forEach(r => {
        if (r.real_name === studentName) {
            const seq = parseInt(String(r.level_sequence), 10);
            if (!isNaN(seq)) units.add(seq);
        }
    });
    return Array.from(units).sort((a, b) => a - b);
};

export const validateExcelData = (data: any[]): { valid: boolean; error?: string } => {
  if (!data || data.length === 0) return { valid: false, error: '文件为空或无法解析数据' };
  const firstRow = data[0];
  const req = ['real_name', 'level_sequence', 'unit_sequence', 'unit_finish_status', 'answer_right_rate', 'first_cost_seconds'];
  const missing = req.filter(field => !(field in firstRow));
  if (missing.length > 0) return { valid: false, error: `缺少必要字段: ${missing.join(', ')}` };
  return { valid: true };
};

const getCompletionBadge = (highCount: number): Badge => {
  if (highCount >= 4) return { name: '金牌完课王', type: 'completion', level: 'gold', description: '金牌成就达成！全课程通关，你就是学习王者！' };
  return { name: '学习之星', type: 'completion', level: 'star', description: '学习之星已点亮！表现非常亮眼，加油向前冲！' };
};

const getAccuracyBadge = (avgAcc: number): Badge => {
  if (avgAcc >= 90) return { name: '学习典范', type: 'accuracy', level: 'model', description: '你的学习质量极高，展现典范级的掌握力。' };
  return { name: '稳定高手', type: 'accuracy', level: 'master', description: '稳定且扎实，保持这个节奏！' };
};

export const processExcelData = (
    rows: StudentDataRow[], 
    targetStudentName: string,
    role: UserRole,
    unitRange?: { min: number, max: number }
): ProcessedReportData | null => {
  if (!rows || rows.length === 0) return null;
  const studentRows = rows.filter(r => r.real_name === targetStudentName);
  if (studentRows.length === 0) return null;

  const lessons: UnitData[] = [];
  const targetUnit = unitRange ? unitRange.max : Math.max(...studentRows.map(r => parseInt(String(r.level_sequence), 10)));
  const unitRows = studentRows.filter(r => parseInt(String(r.level_sequence), 10) === targetUnit);

  // Group by role granularity
  if (role === 'headteacher') {
    unitRows.forEach(r => {
      const seq = parseInt(String(r.unit_sequence), 10);
      const acc = parseRate(r.answer_right_rate);
      lessons.push({
        unitNumber: seq,
        unitName: seq === 0 ? '课前测' : `第${seq}讲`,
        timeSpentSeconds: parseSeconds(r.first_cost_seconds),
        status: r.unit_finish_status === '完课' ? 'high' : 'low',
        statusLabel: r.unit_finish_status === '完课' ? '已完成' : '学习中',
        accuracy: acc,
        classAccuracy: 0, // Calculated later
        wrongCount: parseInt(String(r.wrong_answer_count || Math.round(10 * (1 - acc / 100)))),
        analysis: ''
      });
    });
    lessons.sort((a, b) => a.unitNumber - b.unitNumber);
  } else {
    // Original Counselor logic: unit granularity
    const unitMap = new Map<number, UnitData>();
    studentRows.forEach(r => {
        const uSeq = parseInt(String(r.level_sequence), 10);
        if (unitRange && (uSeq < unitRange.min || uSeq > unitRange.max)) return;
        if (!unitMap.has(uSeq)) {
            unitMap.set(uSeq, {
                unitNumber: uSeq, unitName: `第${uSeq}单元`, timeSpentSeconds: 0, status: 'low',
                statusLabel: '学习中', accuracy: 0, classAccuracy: 0, wrongCount: 0, analysis: ''
            });
        }
        const u = unitMap.get(uSeq)!;
        u.timeSpentSeconds += parseSeconds(r.first_cost_seconds);
        u.accuracy = (u.accuracy + parseRate(r.answer_right_rate)) / 2;
        if (r.unit_finish_status === '完课') u.status = 'high';
    });
    lessons.push(...Array.from(unitMap.values()).sort((a, b) => a.unitNumber - b.unitNumber));
  }

  // Global Averages Calculation
  lessons.forEach(l => {
      const allStudentsInGroup = rows.filter(r => {
          const val = role === 'headteacher' ? parseInt(String(r.unit_sequence), 10) : parseInt(String(r.level_sequence), 10);
          return val === l.unitNumber;
      });
      const avg = allStudentsInGroup.reduce((sum, r) => sum + parseRate(r.answer_right_rate), 0) / (allStudentsInGroup.length || 1);
      l.classAccuracy = avg;
  });

  const totalTime = lessons.reduce((s, l) => s + l.timeSpentSeconds, 0);
  const avgAcc = lessons.reduce((s, l) => s + l.accuracy, 0) / (lessons.length || 1);

  // Analysis Logic
  let trend: TrendAnalysis = { status: 'stable', title: '表现平稳', content: '' };
  if (role === 'headteacher') {
      const preTest = lessons.find(l => l.unitNumber === 0);
      const latest = lessons[lessons.length - 1];
      const allRising = lessons.every((l, i) => i === 0 || l.accuracy >= lessons[i-1].accuracy);

      if (allRising && lessons.length >= 3) {
          trend = { status: 'rising', title: '完美的阶梯式成长！', content: `课程设计的每一步挑战，孩子都步步为营，正确率从${lessons[0].accuracy.toFixed(0)}%一路稳定升至${latest.accuracy.toFixed(0)}%。这正是科学学习路径与孩子努力同频共振的证明。` };
      } else if (preTest && latest.accuracy > preTest.accuracy) {
          trend = { status: 'improving', title: '首尾进步型', content: `太棒了！对比课前测（正确率${preTest.accuracy.toFixed(0)}%），宝贝在第${latest.unitNumber}课的正确率已提升至${latest.accuracy.toFixed(0)}%，${(latest.accuracy - preTest.accuracy).toFixed(0)}个百分点的跨越清晰展现了进步！` };
      } else {
          trend = { status: 'stable', title: '过程价值型', content: `值得点赞！从课前到第${latest.unitNumber}节课的全程学习，宝贝展现了出色的坚持与思考习惯。面对不断升级的挑战仍兴趣盎然，这份专注力是未来突破的最大潜力。` };
      }
  } else {
      trend = { status: 'stable', title: '稳步提升', content: '继续保持良好的学习状态！' };
  }

  return {
    studentName: targetStudentName, grade: translateGrade(studentRows[0]?.package_grade),
    teacher: studentRows[0]?.counselor_name || '老师', role,
    totalTimeSeconds: totalTime, avgTimePerSession: totalTime / (lessons.length || 1),
    timeComment: role === 'headteacher' ? '一节课20分钟，短时高效，每天练出效果！' : '学习效率很高，表现出色。',
    completionBadge: getCompletionBadge(lessons.filter(l => l.status === 'high').length),
    accuracyBadge: getAccuracyBadge(avgAcc),
    completedUnitsCount: lessons.filter(l => l.status === 'high').length,
    units: lessons, trendAnalysis: trend,
    monthlySummary: { milestone: '', highlights: [], improvements: [] }
  };
};

export const getStudentSummaries = (rows: StudentDataRow[]) => {
  const map = new Map<string, any>();
  rows.forEach(r => {
    if (!map.has(r.real_name)) {
      map.set(r.real_name, { name: r.real_name, grade: translateGrade(r.package_grade), teacher: r.counselor_name, unitCount: 0, lastUnit: 0 });
    }
    const s = map.get(r.real_name)!;
    s.unitCount++;
    s.lastUnit = Math.max(s.lastUnit, parseInt(String(r.level_sequence), 10));
  });
  return Array.from(map.values());
};

import React, { useState } from 'react';
import FileUpload from './components/FileUpload';
import ReportView, { ThemeType } from './components/ReportView';
import StudentList from './components/StudentList';
import { StudentDataRow, ProcessedReportData, UserRole } from './types';
import { processExcelData, getAvailableUnits } from './utils';

type AppView = 'upload' | 'list' | 'report';

function App() {
  const [view, setView] = useState<AppView>('upload');
  const [role, setRole] = useState<UserRole>('counselor');
  const [rawData, setRawData] = useState<StudentDataRow[]>([]);
  const [reportData, setReportData] = useState<ProcessedReportData | null>(null);

  const [selectedStudentName, setSelectedStudentName] = useState<string | null>(null);
  const [availableUnits, setAvailableUnits] = useState<number[]>([]);
  const [unitRange, setUnitRange] = useState<{ min: number, max: number }>({ min: 1, max: 1 });
  const [currentTheme, setCurrentTheme] = useState<ThemeType>('default');

  const handleDataLoaded = (data: StudentDataRow[]) => {
    setRawData(data);
    setView('list');
  };

  const handleSelectStudent = (studentName: string) => {
    const units = getAvailableUnits(rawData, studentName);
    if (units.length === 0) return alert('该学生没有有效数据');

    const min = units[0];
    const max = units[units.length - 1];
    setAvailableUnits(units);
    setUnitRange({ min, max });
    setSelectedStudentName(studentName);

    const processed = processExcelData(rawData, studentName, role, { min, max });
    if (processed) {
      setReportData(processed);
      setView('report');
    }
  };

  const handleUnitRangeChange = (min: number, max: number) => {
    if (!selectedStudentName) return;
    setUnitRange({ min, max });
    const processed = processExcelData(rawData, selectedStudentName, role, { min, max });
    if (processed) setReportData(processed);
  };

  const handleReset = () => {
    setRawData([]); setReportData(null); setSelectedStudentName(null); setView('upload');
  };

  return (
    <div className="min-h-screen pb-10 bg-slate-50 font-sans">
      <header className="bg-white border-b-4 border-indigo-100 py-4 mb-8 shadow-sm">
        <div className="container mx-auto px-4 flex justify-between items-center">
            <h1 className="text-2xl font-black text-indigo-600 flex items-center gap-2 cursor-pointer" onClick={handleReset}>
                🎓 学习情况报告生成器
            </h1>
        </div>
      </header>

      <main className="container mx-auto px-4">
        {view === 'upload' && (
          <FileUpload onDataLoaded={handleDataLoaded} role={role} onRoleChange={setRole} />
        )}
        {view === 'list' && (
          <StudentList data={rawData} onSelectStudent={handleSelectStudent} onReupload={handleReset} />
        )}
        {view === 'report' && reportData && (
          <ReportView 
            data={reportData} rawData={rawData} onReset={handleReset} 
            onBack={() => setView('list')} availableUnits={availableUnits}
            currentRange={unitRange} onRangeChange={handleUnitRangeChange}
            currentTheme={currentTheme} onThemeChange={setCurrentTheme}
          />
        )}
      </main>
    </div>
  );
}

export default App;

