const calculateRankings = (allRows: StudentDataRow[], range: { min: number, max: number }, role: string) => {
    const studentMap = new Map<string, { total: number, count: number, id: any }>();
    allRows.forEach(r => {
        const seq = parseInt(String(role === 'headteacher' ? r.unit_sequence : r.level_sequence), 10);
        if (isNaN(seq) || seq < range.min || seq > range.max) return;
        if (!studentMap.has(r.real_name)) studentMap.set(r.real_name, { total: 0, count: 0, id: r.user_id });
        const e = studentMap.get(r.real_name)!;
        e.total += parseRate(r.answer_right_rate); e.count++;
    });
    const res = Array.from(studentMap.entries()).map(([name, v]) => ({ name, userId: v.id, avgAccuracy: v.total / v.count, rank: 0 }));
    res.sort((a, b) => b.avgAccuracy - a.avgAccuracy);
    res.forEach((r, i) => r.rank = i + 1);
    return { rankings: res, total: res.length };
};

const ReportView: React.FC<any> = ({ data, rawData, onReset, onBack, availableUnits, currentRange, onRangeChange, currentTheme, onThemeChange }) => {
  const t = themes[currentTheme];
  const c = t.colors;
  const isHT = data.role === 'headteacher';

  const [selectedCurriculumKey, setSelectedCurriculumKey] = useState<string>(Object.keys(CURRICULA)[0]);
  const currentCurriculum = CURRICULA[selectedCurriculumKey] || [];

  const { rankings, total } = useMemo(() => calculateRankings(rawData, currentRange, data.role), [rawData, currentRange, data.role]);
  const myRank = rankings.find(r => r.name === data.studentName);

  const displayedRanks = useMemo(() => {
      const idx = rankings.findIndex(r => r.name === data.studentName);
