const calculateRankings = (allRows: StudentDataRow[], range: { min: number, max: number }, role: string) => {
    const studentMap = new Map<string, { accuracies: Record<number, number>, totalScore: number, avgAccuracy: number, count: number, id: any }>();
    allRows.forEach(r => {
        const isHT = role === 'headteacher';
        const unitSeq = parseInt(String(r.level_sequence), 10);
        const lessonSeq = parseInt(String(r.unit_sequence), 10);

        const filterVal = isHT ? lessonSeq : unitSeq;
        if (isNaN(filterVal) || filterVal < range.min || filterVal > range.max) {
            // Special case for HT: Pre-test (seq 0) might be outside range min (usually 1) but we need it for display if context is the unit
            if (!(isHT && lessonSeq === 0 && unitSeq === range.max)) return;
        }

        if (!studentMap.has(r.real_name)) {
            studentMap.set(r.real_name, { accuracies: {}, totalScore: 0, avgAccuracy: 0, count: 0, id: r.user_id });
        }
        const e = studentMap.get(r.real_name)!;
        const rate = parseRate(r.answer_right_rate);
        e.accuracies[lessonSeq] = rate;

        if (isHT) {
            if (lessonSeq !== 0) {
                e.totalScore += rate;
            }
        } else {
            e.avgAccuracy = (e.avgAccuracy * e.count + rate) / (e.count + 1);
            e.count++;
        }
    });

    const res = Array.from(studentMap.entries()).map(([name, v]) => ({ 
        name, 
        userId: v.id, 
        accuracies: v.accuracies,
        totalScore: Math.round(v.totalScore),
        avgAccuracy: v.avgAccuracy,
        rank: 0 
    }));

    if (role === 'headteacher') {
        res.sort((a, b) => b.totalScore - a.totalScore);
    } else {
        res.sort((a, b) => b.avgAccuracy - a.avgAccuracy);
    }

    res.forEach((r, i) => r.rank = i + 1);
    return { rankings: res, total: res.length };
};

