const calculateRankings = (allRows: StudentDataRow[], range: { min: number, max: number }, role: string) => {
    const studentMap = new Map<string, { accuracies: Record<number, number>, totalScore: number, avgAccuracy: number, count: number, id: any }>();

    allRows.forEach(r => {
        const isHT = role === 'headteacher';
        const unitSeq = parseInt(String(r.level_sequence), 10);
        const lessonSeq = parseInt(String(r.unit_sequence), 10);

        // Filtering Logic:
        // HT Mode: Look for all lessons (L0-L5) that belong to the targeted Unit (range.max)
        // Counselor Mode: Look for Units (level_sequence) between min and max
        if (isHT) {
            if (unitSeq !== range.max) return;
        } else {
            if (isNaN(unitSeq) || unitSeq < range.min || unitSeq > range.max) return;
        }

        if (!studentMap.has(r.real_name)) {
            studentMap.set(r.real_name, { accuracies: {}, totalScore: 0, avgAccuracy: 0, count: 0, id: r.user_id });
        }
        const e = studentMap.get(r.real_name)!;
        const rate = parseRate(r.answer_right_rate);
        e.accuracies[lessonSeq] = rate;

        if (isHT) {
            // Comprehensive score only sums L1-L5 (exclude L0)
            if (lessonSeq >= 1 && lessonSeq <= 5) {
                // Since totalScore is used for ranking, we sum up current accuracies
                // We calculate this final sum in the map conversion step to handle duplicates if any
            }
        } else {
            e.avgAccuracy = (e.avgAccuracy * e.count + rate) / (e.count + 1);
            e.count++;
        }
    });

    const res = Array.from(studentMap.entries()).map(([name, v]) => {
        let totalScoreHT = 0;
        if (role === 'headteacher') {
            // Sum of L1 through L5
            [1, 2, 3, 4, 5].forEach(l => {
                if (v.accuracies[l] !== undefined) totalScoreHT += v.accuracies[l];
            });
        }

        return { 
            name, 
            userId: v.id, 
            accuracies: v.accuracies,
            totalScore: Math.round(totalScoreHT),
            avgAccuracy: v.avgAccuracy,
            rank: 0 
        };
    });

    if (role === 'headteacher') {
        res.sort((a, b) => b.totalScore - a.totalScore);
    } else {
        res.sort((a, b) => b.avgAccuracy - a.avgAccuracy);
    }

    res.forEach((r, i) => r.rank = i + 1);
    return { rankings: res, total: res.length };
};

const ReportView: React.FC<any> = ({ data, rawData, onReset, onBack, availableUnits, currentRange, onRangeChange, currentTheme, onThemeChange }) => {
  const t = themes[currentTheme];
  const c = t.colors;
  const isHT = data.role === 'headteacher';

  const [selectedCurriculumKey, setSelectedCurriculumKey] = useState<string>(Object.keys(CURRICULA)[0]);
  const currentCurriculum = CURRICULA[selectedCurriculumKey] || [];

  const { rankings, total } = useMemo(() => calculateRankings(rawData, currentRange, data.role), [rawData, currentRange, data.role]);
  const myRank = rankings.find(r => r.name === data.studentName);

  const displayedRanks = useMemo(() => {
      const idx = rankings.findIndex(r => r.name === data.studentName);
      return idx === -1 ? [] : rankings.slice(Math.max(0, idx - 5), Math.min(rankings.length, idx + 6));
  }, [rankings, data.studentName]);

  const errorAnalysis = useMemo(() => {
      if (!isHT) return null;
      const preTest = data.units.find((u: UnitData) => u.unitNumber === 0);
      const latest = data.units[data.units.length - 1];
      if (!preTest || !latest) return null;
      const decr = data.units.every((u: UnitData, i: number) => i === 0 || u.wrongCount <= (data.units[i-1]?.wrongCount ?? 999));
      if (decr) return "步步为营，错题持续减少，学习习惯与效果俱佳，进步飞速！";
      if (latest.wrongCount < preTest.wrongCount) return "错题日益减少，可见知识掌握越发扎实牢固！";
      return "挑战升级，敢于尝试复杂题目，正是思维深入拓展的表现！";
  }, [data.units, isHT]);

