  const myRank = rankings.find(r => r.name === data.studentName);

  const displayedRanks = useMemo(() => {
      const idx = rankings.findIndex(r => r.name === data.studentName);
      return idx === -1 ? [] : rankings.slice(Math.max(0, idx - 5), Math.min(rankings.length, idx + 6));
  }, [rankings, data.studentName]);

  const errorAnalysis = useMemo(() => {
      if (!isHT) return null;
      const preTest = data.units.find((u: UnitData) => u.unitNumber === 0);
      const latest = data.units[data.units.length - 1];
      if (!preTest || !latest) return null;
      const decr = data.units.every((u: UnitData, i: number) => i === 0 || u.wrongCount <= (data.units[i-1]?.wrongCount ?? 999));
      if (decr) return "步步为营，错题持续减少，学习习惯与效果俱佳，进步飞速！";
      if (latest.wrongCount < preTest.wrongCount) return "错题日益减少，可见知识掌握越发扎实牢固！";
      return "挑战升级，敢于尝试复杂题目，正是思维深入拓展的表现！";
  }, [data.units, isHT]);

  const getRankComment = () => {
      if (!myRank) return "";
      const p = myRank.rank / total;
      if (p <= 0.2) return `非常优秀！${data.studentName}同学在本次班级（共${total}人）中高居第${myRank.rank}名。宝贝总能将复杂问题拆解清晰、步步推进，并主动攻克丰富的拓展题型，这种扎实的解题思路和举一反三的能力，正是领先的关键！`;
      if (p <= 0.5) return `稳步前进！${data.studentName}同学在班级（共${total}人）中位列第${myRank.rank}名，已超越半数同学。课程中逐步引导的解题思路和丰富的练习，让孩子收获了扎实的知识与良好的思维习惯，请继续保持！`;
      return `为${data.studentName}同学的坚持点赞！学习是一场探索，重要的是保持兴趣与勇气。宝贝展现的专注和闯关决心已是成功的开始，继续加油！相信在未来的学习之旅中会有更大的突破！`;
  };

  const getLessonName = (uNum: number) => {
    if (uNum === 0) return '课前测';
    if (isHT && uNum >= 1 && uNum <= 5) {
        return currentCurriculum[uNum - 1] || `第${uNum}讲`;
    }
    return isHT ? `第${uNum}讲` : `第${uNum}单元`;
  };

  const chartUnits = useMemo(() => {
      return data.units.map((u: UnitData) => ({
          ...u,
          unitName: u.unitNumber === 0 ? '课前测' : `第${u.unitNumber}讲`
      }));
  }, [data.units, isHT]);

  const tableUnits = useMemo(() => {
      return data.units.map((u: UnitData) => ({
          ...u,
          unitName: getLessonName(u.unitNumber)
      }));
  }, [data.units, isHT, currentCurriculum]);

  const maxWrongCount = useMemo(() => {
      const counts = data.units.map((u: any) => u.wrongCount);
      return counts.length > 0 ? Math.max(...counts, 10) : 10;
  }, [data.units]);

  const rankingLessonCols = [0, 1, 2, 3, 4, 5];

  return (
    <div className={`max-w-6xl mx-auto my-6 font-sans ${c.textMain}`}>
      <div className="mb-6 flex flex-col md:flex-row justify-between items-center px-4 gap-4 print:hidden">
        <div className="flex gap-3">
            <button onClick={onBack} className="bg-white px-6 py-2.5 rounded-full border-2 border-slate-100 shadow-sm font-black flex items-center gap-2 transition-all hover:scale-105"><ArrowLeft className="w-5 h-5"/>返回</button>
            <button onClick={() => window.print()} className={`px-8 py-2.5 rounded-full font-black flex items-center gap-2 transition-all active:translate-y-1 ${c.primary}`}><Download className="w-5 h-5"/>打印/导出</button>
        </div>
        <div className="flex flex-wrap gap-3 items-center justify-center">
            {isHT && (
                <div className="bg-white px-4 py-2 rounded-full border-2 border-slate-100 shadow-sm flex items-center gap-2">
                    <Book className="w-4 h-4 text-slate-300"/>
                    <select value={selectedCurriculumKey} onChange={e => setSelectedCurriculumKey(e.target.value)} className="bg-transparent font-black text-sm outline-none cursor-pointer">
                        {Object.keys(CURRICULA).map(k => <option key={k} value={k}>{k}课表</option>)}
                    </select>
                </div>
            )}
            <div className="bg-white p-1 rounded-full border-2 border-slate-100 shadow-sm flex">
                {(Object.keys(themes) as ThemeType[]).map(k => (
                    <button key={k} onClick={() => onThemeChange(k)} className={`px-4 py-1.5 rounded-full text-xs font-black transition-all ${currentTheme === k ? 'bg-slate-800 text-white shadow-md' : 'text-slate-400'}`}>{themes[k].label}</button>
                ))}
            </div>
            {!isHT && (
                <div className="bg-white px-4 py-2 rounded-full border-2 border-slate-100 shadow-sm flex items-center gap-2">
                    <Filter className="w-4 h-4 text-slate-300"/>
                    <select value={currentRange.min} onChange={e => onRangeChange(parseInt(e.target.value), currentRange.max)} className="bg-transparent font-black text-sm outline-none cursor-pointer">
                        {availableUnits.map((u: number) => <option key={u} value={u}>第{u}单元</option>)}
                    </select>
                    <span className="text-slate-200">~</span>
                    <select value={currentRange.max} onChange={e => onRangeChange(currentRange.min, parseInt(e.target.value))} className="bg-transparent font-black text-sm outline-none cursor-pointer">
                        {availableUnits.map((u: number) => <option key={u} value={u}>第{u}单元</option>)}
                    </select>
                </div>
            )}
        </div>
      </div>

      <div className={`${c.bgMain} ${t.containerClass} ${c.border} overflow-hidden relative print:shadow-none transition-all duration-700`}>
        <div className={`${c.headerBg} py-12 text-center relative border-b-4 ${c.border}`}>
            <h1 className={`text-4xl font-black ${c.headerText} tracking-tight drop-shadow-sm flex items-center justify-center gap-3`}>
                {currentTheme === 'boy' ? <Rocket className="w-10 h-10 animate-pulse"/> : <Crown className="w-10 h-10 text-yellow-300 fill-current"/>}
                {data.studentName} {isHT ? `专属学习报告` : `${currentRange.min}-${currentRange.max}单元 学习报告`}
            </h1>
        </div>

        <div className={`flex flex-col md:flex-row border-b-4 ${c.border}`}>
            <div className={`w-full md:w-1/3 ${c.profileBg} p-10 border-b-4 md:border-b-0 md:border-r-4 ${c.border} flex flex-col justify-center`}>
                <div className="flex items-center gap-4 mb-8">
                    <div className={`w-16 h-16 rounded-3xl flex items-center justify-center border-4 shadow-sm ${currentTheme === 'boy' ? 'bg-blue-600 text-white border-blue-200' : 'bg-rose-100 text-stone-500 border-white'}`}>
                        <User className="w-8 h-8"/>
                    </div>
                    <div>
