                        <p className="text-xs opacity-40 font-bold uppercase tracking-widest">Profile Card</p>
                    </div>
                </div>
                <div className={`${t.cardClass} bg-white p-8 space-y-6`}>
                    <div className="flex justify-between border-b pb-3"><span className="font-bold opacity-40">姓名</span><span className="font-black text-xl">{data.studentName}</span></div>
                    <div className="flex justify-between border-b pb-3"><span className="font-bold opacity-40">年级</span><span className="px-4 py-1 rounded-full bg-slate-100 font-bold text-sm">{data.grade}</span></div>
                    <div className="flex justify-between"><span className="font-bold opacity-40">老师</span><span className="font-bold">{data.teacher}</span></div>
