                {isHT ? (
                    <div className="grid grid-cols-2 gap-6">
                        {data.htBadges?.map((badge: Badge) => (
                            <div key={badge.name} className={`${t.cardClass} bg-white/80 backdrop-blur-sm p-4 flex flex-col items-center justify-center shadow-sm`}>
                                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-2 shadow-sm ${currentTheme === 'boy' ? 'bg-blue-600 text-white' : 'bg-rose-50 text-rose-300'}`}>
                                    {badge.level === 'progress' ? <Zap className="w-6 h-6"/> : badge.level === 'potential' ? <Rocket className="w-6 h-6"/> : <Star className="w-6 h-6"/>}
                                </div>
                                <h4 className="font-black text-sm mb-1">{badge.name}</h4>
                                <div className="flex gap-0.5 mb-2">
                                    {[...Array(5)].map((_, i) => (
                                        <Star key={i} className={`w-3.5 h-3.5 ${i < (badge.stars || 0) ? 'text-yellow-400 fill-yellow-400' : 'text-slate-200 fill-slate-100'}`} />
                                    ))}
                                </div>
                                <p className="text-[10px] font-bold text-slate-400/80 text-center leading-tight italic">“{badge.description}”</p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="flex gap-10">
                        <div className="flex-1 flex flex-col items-center">
                            <div className={`w-28 h-28 rounded-[2rem] flex items-center justify-center shadow-lg transform rotate-3 mb-4 ${currentTheme === 'boy' ? 'bg-amber-400 border-4 border-white' : 'bg-rose-50 border-rose-100 border-2'}`}>
                                <Star className={`w-12 h-12 ${currentTheme === 'boy' ? 'text-white' : 'text-rose-300'}`}/>
                            </div>
                            <p className="font-black text-lg mb-2">{data.completionBadge.name}</p>
                            <div className={`${t.cardClass} bg-white/60 p-4 text-center text-xs font-bold leading-relaxed`}>{data.completionBadge.description}</div>
                        </div>
                        <div className="flex-1 flex flex-col items-center">
                            <div className={`w-28 h-28 rounded-[2rem] flex items-center justify-center shadow-lg transform -rotate-3 mb-4 ${currentTheme === 'boy' ? 'bg-blue-600 border-4 border-white' : 'bg-amber-50 border-amber-100 border-2'}`}>
                                <Target className="w-12 h-12 text-white"/>
                            </div>
                            <p className="font-black text-lg mb-2">{data.accuracyBadge.name}</p>
                            <div className={`${t.cardClass} bg-white/60 p-4 text-center text-xs font-bold leading-relaxed`}>{data.accuracyBadge.description}</div>
                        </div>
                    </div>
                )}
            </div>
        </div>

        <div className="flex flex-col lg:flex-row min-h-[480px]">
            <div className={`w-full ${isHT ? 'lg:w-[38%]' : 'lg:w-3/5'} border-b-4 lg:border-b-0 lg:border-r-4 ${c.border} bg-white p-8`}>
                <div className="flex justify-between items-center mb-8">
                    <h3 className="text-2xl font-black flex items-center gap-3"><BarChart2 className="w-8 h-8 text-indigo-500"/>{isHT ? '学习记录' : '学习闯关记录'}</h3>
                    <div className="px-6 py-2 bg-indigo-50 rounded-full text-indigo-600 font-black text-xs">{data.timeComment}</div>
                </div>
                <div className={`${t.cardClass} border-2 overflow-hidden mb-6`}>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead className={c.tableHeader}>
                                <tr>
                                    <th className="px-4 py-4 text-left whitespace-nowrap">{isHT ? '讲次' : '讲次/单元'}</th>
                                    <th className="px-4 py-4 text-center">学习时长</th>
                                    {!isHT && <th className="px-4 py-4 text-center">正确率</th>}
                                    {isHT && <th className="px-4 py-4 text-right">错误次数统计</th>}
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-50">
                                {tableUnits.map((u: any, i: number) => (
                                    <tr key={u.unitNumber} className={`transition-colors ${i % 2 === 0 ? 'bg-white' : 'bg-slate-50/50'} hover:bg-slate-100`}>
                                        <td className="px-4 py-5 font-black whitespace-nowrap text-xs">{u.unitName}</td>
                                        <td className="px-4 py-5 text-center font-bold opacity-50 text-xs">{formatDuration(u.timeSpentSeconds)}</td>
                                        {!isHT && <td className="px-4 py-5 text-center font-black text-sm">{u.accuracy.toFixed(1)}%</td>}
                                        {isHT && (
                                            <td className="px-4 py-5 text-right">
                                                <div className="flex items-center justify-end gap-2">
                                                    <span className="text-[10px] font-black text-rose-400 whitespace-nowrap">{u.wrongCount}次</span>
                                                    <div className="w-12 md:w-16 bg-rose-50 rounded-full h-1.5 overflow-hidden">
                                                        <div 
                                                            className="bg-rose-400 h-full rounded-full transition-all duration-1000" 
                                                            style={{ width: `${Math.min(100, (u.wrongCount / maxWrongCount) * 100)}%` }}
                                                        ></div>
                                                    </div>
                                                </div>
                                            </td>
                                        )}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
                {isHT && errorAnalysis && (
                    <div className={`${t.cardClass} bg-rose-50 border-rose-100 p-4 flex gap-4 items-center`}>
                        <AlertCircle className="w-6 h-6 text-rose-400 shrink-0"/>
                        <div>
                            <p className="font-bold text-xs text-rose-500/90 italic leading-relaxed">{errorAnalysis}</p>
                        </div>
                    </div>
                )}
            </div>

            <div className={`w-full ${isHT ? 'lg:w-[62%]' : 'lg:w-2/5'} ${c.chartBg} p-8 flex flex-col`}>
                <h3 className="text-2xl font-black mb-8 flex items-center gap-3"><Lightbulb className="w-8 h-8 text-amber-500"/>课程正确率趋势 (我的 vs 班级平均)</h3>
                <div className={`${t.cardClass} bg-white p-6 h-[400px] mb-8 relative shadow-md border-indigo-50 border-4`}>
                    <ReportChart data={chartUnits} color={isHT ? '#818cf8' : '#f97316'}/>
                    <div className="absolute top-4 right-6 flex items-center gap-4 text-[9px] font-black uppercase tracking-widest text-slate-400">
                        <div className="flex items-center gap-1"><div className={`w-3 h-1 ${isHT ? 'bg-[#818cf8]' : 'bg-[#f97316]'}`}></div>我的成绩</div>
                        <div className="flex items-center gap-1"><div className="w-3 h-1 bg-slate-200 border-t border-dashed border-slate-400"></div>班级平均</div>
                    </div>
                </div>
                <div className={`${t.cardClass} bg-white p-6 flex-grow shadow-sm border-2 ${c.border}`}>
                    <h4 className={`text-lg font-black mb-4 flex items-center gap-2 ${c.headerText}`}><Zap className="w-5 h-5 text-yellow-400 fill-current"/>{data.trendAnalysis.title}</h4>
                    <p className="font-bold text-sm leading-relaxed text-justify opacity-80 italic">“{data.trendAnalysis.content}”</p>
                </div>
            </div>
        </div>

        <div className="bg-white p-10">
            <div className={`${t.cardClass} border-2 ${c.border} overflow-hidden shadow-sm`}>
                <div className={`${c.rankingHeaderBg} p-6 border-b flex justify-between items-center`}>
                    <h3 className="text-2xl font-black flex items-center gap-3"><ListOrdered className="w-8 h-8 text-stone-400"/>正确率排名</h3>
                    <span className="font-bold text-xs opacity-40">共有 {total} 名学员参与本次统计</span>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                        <thead className="bg-slate-50/80 text-slate-400 font-bold text-[10px] uppercase tracking-wider">
                            <tr>
                                <th className="px-6 py-4 text-left w-20">名次</th>
                                <th className="px-6 py-4 text-left">姓名</th>
                                {isHT && rankingLessonCols.map(col => (
                                    <th key={col} className={`px-2 py-4 text-center whitespace-nowrap ${col === 0 ? 'bg-amber-50 text-amber-600 border-r-2 border-amber-100' : ''}`}>
                                        {col === 0 ? '课前测' : `L${col}`}
                                    </th>
                                ))}
                                <th className="px-6 py-4 text-right">
                                    {isHT ? '综合得分' : '平均正确率'}
                                </th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {displayedRanks.map(r => {
                                const isMe = r.name === data.studentName;
                                const masked = isMe ? r.name : (r.name.charAt(0) + 'x'.repeat(Math.min(r.name.length - 1, 1))).slice(0, 4);
                                return (
                                    <tr key={r.name} className={`${isMe ? c.rankingHighlightRow : 'hover:bg-slate-50/50'} transition-all`}>
                                        <td className="px-6 py-5">
                                            <span className={`w-9 h-9 rounded-2xl flex items-center justify-center font-black ${r.rank <= 3 ? 'bg-amber-100 text-amber-600' : 'bg-slate-100 text-slate-400'} ${isMe ? 'ring-4 ring-amber-400/20' : ''}`}>
                                                {r.rank}
                                            </span>
                                        </td>
                                        <td className={`px-6 py-5 font-black text-base ${isMe ? 'text-amber-600' : 'opacity-70'}`}>
                                            {masked}{isMe && <span className="ml-2 text-[10px] bg-amber-400 text-white px-2 py-0.5 rounded-full">我</span>}
                                        </td>
                                        {isHT && rankingLessonCols.map(col => (
                                            <td key={col} className={`px-2 py-5 text-center font-bold text-[10px] ${col === 0 ? 'bg-amber-50/30 border-r-2 border-amber-100/50' : ''} ${r.accuracies[col] !== undefined ? 'text-slate-600' : 'text-slate-200'}`}>
                                                {r.accuracies[col] !== undefined ? `${r.accuracies[col].toFixed(0)}%` : '-'}
                                            </td>
                                        ))}
                                        <td className="px-6 py-5 text-right font-black text-lg whitespace-nowrap">
                                            {isHT ? r.totalScore : `${r.avgAccuracy.toFixed(1)}%`}
                                        </td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
                <div className={`${c.rankingBannerBg} ${c.rankingBannerText} p-8 text-center font-black text-sm italic leading-relaxed`}>
                    {getRankComment()}
                </div>
            </div>
        </div>

        <div className={`${c.teacherSection} p-12 text-center relative overflow-hidden`}>
            <div className="relative z-10 max-w-3xl mx-auto">
                <MessageCircleHeart className="w-12 h-12 mx-auto mb-6 opacity-40"/>
                <p className="text-2xl font-black italic mb-4 opacity-90 leading-snug">“ 学习不仅是分数的累积，更是思维的破壳而出。亲爱的家长，宝贝正在用每一个百分点的进步，书写属于自己的未来！让我们共同呵护这份成长。 ”</p>
                <p className="font-bold opacity-60">— 您的辅导老师 {data.teacher}</p>
            </div>
        </div>
      </div>
    </div>
  );
};

export default ReportView;

import React, { useState } from 'react';
import FileUpload from './components/FileUpload';
import ReportView, { ThemeType } from './components/ReportView';
import StudentList from './components/StudentList';
import { StudentDataRow, ProcessedReportData, UserRole } from './types';
import { processExcelData, getAvailableUnits, CURRICULA } from './utils';

type AppView = 'upload' | 'list' | 'report';

function App() {
  const [view, setView] = useState<AppView>('upload');
  const [role, setRole] = useState<UserRole>('counselor');
  const [rawData, setRawData] = useState<StudentDataRow[]>([]);
  const [reportData, setReportData] = useState<ProcessedReportData | null>(null);

  const [selectedStudentName, setSelectedStudentName] = useState<string | null>(null);
  const [availableUnits, setAvailableUnits] = useState<number[]>([]);
  const [unitRange, setUnitRange] = useState<{ min: number, max: number }>({ min: 1, max: 1 });
  const [currentTheme, setCurrentTheme] = useState<ThemeType>('default');
  const [selectedCurriculumKey, setSelectedCurriculumKey] = useState<string>(Object.keys(CURRICULA)[0]);

  const handleDataLoaded = (data: StudentDataRow[]) => {
    setRawData(data);
    setView('list');
  };

  const handleSelectStudent = (studentName: string) => {
    const units = getAvailableUnits(rawData, studentName);
    if (units.length === 0) return alert('该学生没有有效数据');

    const min = units[0];
    const max = units[units.length - 1];
    setAvailableUnits(units);
    setUnitRange({ min, max });
    setSelectedStudentName(studentName);

    // Smart Curriculum Logic: 
    // If switching students, only change curriculum if the grade changes.
    // Except if it's already a variant of that grade (like '一年级' vs '一年级弹窗').
    const studentRow = rawData.find(r => r.real_name === studentName);
    if (studentRow) {
      const studentGrade = studentRow.package_grade || '';
      const mappedGrade = studentGrade.toLowerCase().includes('one') ? '一年级' : 
                          studentGrade.toLowerCase().includes('two') ? '二年级' :
                          studentGrade.toLowerCase().includes('three') ? '三年级' :
                          studentGrade.toLowerCase().includes('four') ? '四年级' :
                          studentGrade.toLowerCase().includes('five') ? '五年级' :
                          studentGrade.toLowerCase().includes('six') ? '六年级' : '';

      if (mappedGrade && !selectedCurriculumKey.startsWith(mappedGrade)) {
        setSelectedCurriculumKey(mappedGrade);
      }
    }

    const processed = processExcelData(rawData, studentName, role, { min, max });
    if (processed) {
      setReportData(processed);
      setView('report');
    }
  };

  const handleSwitchStudentById = (userId: string | number) => {
    const student = rawData.find(r => String(r.user_id) === String(userId));
    if (student) {
      handleSelectStudent(student.real_name);
    } else {
      alert(`未找到 ID 为 ${userId} 的学员`);
    }
  };

  const handleUnitRangeChange = (min: number, max: number) => {
    if (!selectedStudentName) return;
    setUnitRange({ min, max });
    const processed = processExcelData(rawData, selectedStudentName, role, { min, max });
    if (processed) setReportData(processed);
  };

  const handleReset = () => {
    setRawData([]); setReportData(null); setSelectedStudentName(null); setView('upload');
  };

  return (
    <div className="min-h-screen pb-10 bg-slate-50 font-sans">
      <header className="bg-white border-b-4 border-indigo-100 py-4 mb-8 shadow-sm print:hidden">
        <div className="container mx-auto px-4 flex justify-between items-center">
            <h1 className="text-2xl font-black text-indigo-600 flex items-center gap-2 cursor-pointer" onClick={handleReset}>
                🎓 学习情况报告生成器
            </h1>
        </div>
      </header>

      <main className="container mx-auto px-4">
        {view === 'upload' && (
          <FileUpload onDataLoaded={handleDataLoaded} role={role} onRoleChange={setRole} />
        )}
        {view === 'list' && (
          <StudentList data={rawData} onSelectStudent={handleSelectStudent} onReupload={handleReset} />
        )}
        {view === 'report' && reportData && (
          <ReportView 
            data={reportData} 
            rawData={rawData} 
            onReset={handleReset} 
            onBack={() => setView('list')} 
            availableUnits={availableUnits}
            currentRange={unitRange} 
            onRangeChange={handleUnitRangeChange}
            currentTheme={currentTheme} 
            onThemeChange={setCurrentTheme}
            selectedCurriculumKey={selectedCurriculumKey}
            setSelectedCurriculumKey={setSelectedCurriculumKey}
            onSwitchStudentById={handleSwitchStudentById}
          />
        )}
      </main>
    </div>
  );
}

