  return { name: '稳定高手', type: 'accuracy', level: 'master', description: '稳定且扎实，保持这个节奏！' };
};

export const processExcelData = (
    rows: StudentDataRow[], 
    targetStudentName: string,
    role: UserRole,
    unitRange?: { min: number, max: number }
): ProcessedReportData | null => {
  if (!rows || rows.length === 0) return null;
  const studentRows = rows.filter(r => r.real_name === targetStudentName);
  if (studentRows.length === 0) return null;

  const lessons: UnitData[] = [];
  const targetUnit = unitRange ? unitRange.max : Math.max(...studentRows.map(r => parseInt(String(r.level_sequence), 10)));
  const unitRows = studentRows.filter(r => parseInt(String(r.level_sequence), 10) === targetUnit);

  if (role === 'headteacher') {
    unitRows.forEach(r => {
      const seq = parseInt(String(r.unit_sequence), 10);
      const acc = parseRate(r.answer_right_rate);
      const passRate = parseRate(r.pass_rate);

      const allStudentsInThisLesson = rows.filter(row => 
        parseInt(String(row.level_sequence), 10) === targetUnit && 
        parseInt(String(row.unit_sequence), 10) === seq
      );

      // Calculate averages excluding 0%
      const validStudentsAcc = allStudentsInThisLesson.filter(row => parseRate(row.answer_right_rate) > 0);
      const classAvgAcc = validStudentsAcc.length > 0 
        ? validStudentsAcc.reduce((sum, row) => sum + parseRate(row.answer_right_rate), 0) / validStudentsAcc.length 
        : 0;

      const validStudentsPass = allStudentsInThisLesson.filter(row => parseRate(row.pass_rate) > 0);
      const classAvgPass = validStudentsPass.length > 0 
        ? validStudentsPass.reduce((sum, row) => sum + parseRate(row.pass_rate), 0) / validStudentsPass.length 
        : 0;

      lessons.push({
        unitNumber: seq,
        unitName: seq === 0 ? '课前测' : `第${seq}讲`,
        timeSpentSeconds: parseSeconds(r.first_cost_seconds),
        status: r.unit_finish_status === '完课' ? 'high' : 'low',
        statusLabel: r.unit_finish_status === '完课' ? '已完成' : '学习中',
        accuracy: acc,
        classAccuracy: classAvgAcc,
        passRate: passRate,
        classPassRate: classAvgPass,
        // Use first_finish_answer_step_fail_cnt for errors in HT mode
        wrongCount: parseInt(String(r.first_finish_answer_step_fail_cnt ?? r.wrong_answer_count ?? 0)),
        analysis: ''
      });
    });
    lessons.sort((a, b) => a.unitNumber - b.unitNumber);

    const preTest = lessons.find(l => l.unitNumber === 0);
    let progressStars = 0, persistenceStars = 0, timeStars = 0, sprintStars = 0;

    lessons.forEach(l => {
      if (l.unitNumber === 0) return;
      if (preTest && l.accuracy > preTest.accuracy) progressStars++;
      if (l.status === 'high') persistenceStars++;
      if (preTest && l.timeSpentSeconds < preTest.timeSpentSeconds) timeStars++;
      if (l.accuracy > 50) sprintStars++;
    });

    const htBadges: Badge[] = [
      { name: '学习进步徽章', type: 'accuracy', level: 'progress', description: '每一次突破，都是对自我的超越，你是最棒的进步小达人！', stars: Math.min(5, progressStars) },
      { name: '坚持小达人', type: 'completion', level: 'growth', description: '滴水穿石，你的每一份坚持都在为成功的未来铺路，继续保持！', stars: Math.min(5, persistenceStars) },
      { name: '时间小飞侠', type: 'accuracy', level: 'potential', description: '灵动如闪电，你的高效思维让学习变得如此轻松，为你点赞！', stars: Math.min(5, timeStars) },
      { name: '满分冲刺星', type: 'accuracy', level: 'master', description: '瞄准目标，全力以赴，你的专注让每一个关卡都变得简单！', stars: Math.min(5, sprintStars) }
    ];

    const totalTime = lessons.reduce((s, l) => s + l.timeSpentSeconds, 0);
    return {
      studentName: targetStudentName, grade: translateGrade(studentRows[0]?.package_grade),
      teacher: studentRows[0]?.counselor_name || '老师', role,
      totalTimeSeconds: totalTime, avgTimePerSession: totalTime / (lessons.length || 1),
      timeComment: '一节课20分钟，短时高效，每天练出效果！',
      completionBadge: getCompletionBadge(0), 
      accuracyBadge: getAccuracyBadge(0), 
      htBadges,
      completedUnitsCount: lessons.filter(l => l.status === 'high').length,
      units: lessons, 
      trendAnalysis: calculateHTTrend(lessons),
      monthlySummary: { milestone: '', highlights: [], improvements: [] }
    };
  } else {
    const unitMap = new Map<number, UnitData>();
    studentRows.forEach(r => {
        const uSeq = parseInt(String(r.level_sequence), 10);
        if (unitRange && (uSeq < unitRange.min || uSeq > unitRange.max)) return;
        if (!unitMap.has(uSeq)) {
            unitMap.set(uSeq, {
                unitNumber: uSeq, unitName: `第${uSeq}单元`, timeSpentSeconds: 0, status: 'low',
                statusLabel: '学习中', accuracy: 0, classAccuracy: 0, passRate: 0, classPassRate: 0, wrongCount: 0, analysis: ''
            });
        }
        const u = unitMap.get(uSeq)!;
        u.timeSpentSeconds += parseSeconds(r.first_cost_seconds);
        u.accuracy = (u.accuracy + parseRate(r.answer_right_rate)) / 2;
        u.passRate = (u.passRate + parseRate(r.pass_rate)) / 2;
        if (r.unit_finish_status === '完课') u.status = 'high';
    });

    const lessonsList = Array.from(unitMap.values()).sort((a, b) => a.unitNumber - b.unitNumber);
    lessonsList.forEach(l => {
      const allStudentsInThisUnit = rows.filter(row => 
        parseInt(String(row.level_sequence), 10) === l.unitNumber
      );

      const validStudentsAcc = allStudentsInThisUnit.filter(row => parseRate(row.answer_right_rate) > 0);
      l.classAccuracy = validStudentsAcc.length > 0 
        ? validStudentsAcc.reduce((sum, row) => sum + parseRate(row.answer_right_rate), 0) / validStudentsAcc.length 
        : 0;

      const validStudentsPass = allStudentsInThisUnit.filter(row => parseRate(row.pass_rate) > 0);
      l.classPassRate = validStudentsPass.length > 0 
        ? validStudentsPass.reduce((sum, row) => sum + parseRate(row.pass_rate), 0) / validStudentsPass.length 
        : 0;
    });

    const totalTime = lessonsList.reduce((s, l) => s + l.timeSpentSeconds, 0);
    const avgAcc = lessonsList.reduce((s, l) => s + l.accuracy, 0) / (lessonsList.length || 1);

    return {
      studentName: targetStudentName, grade: translateGrade(studentRows[0]?.package_grade),
      teacher: studentRows[0]?.counselor_name || '老师', role,
      totalTimeSeconds: totalTime, avgTimePerSession: totalTime / (lessonsList.length || 1),
      timeComment: '学习效率很高，表现出色。',
      completionBadge: getCompletionBadge(lessonsList.filter(l => l.status === 'high').length),
      accuracyBadge: getAccuracyBadge(avgAcc),
      completedUnitsCount: lessonsList.filter(l => l.status === 'high').length,
      units: lessonsList, 
      trendAnalysis: { status: 'stable', title: '稳步提升', content: '继续保持良好的学习状态！' },
      monthlySummary: { milestone: '', highlights: [], improvements: [] }
    };
  }
};

function calculateHTTrend(lessons: UnitData[]): TrendAnalysis {
    const preTest = lessons.find(l => l.unitNumber === 0);
    const latest = lessons[lessons.length - 1];
    const allRising = lessons.every((l, i) => i === 0 || l.accuracy >= (lessons[i-1]?.accuracy ?? 0));

    if (allRising && lessons.length >= 3) {
        return { status: 'rising', title: '完美的阶梯式成长！', content: `课程设计的每一步挑战，孩子都步步为营，正确率从${lessons[0].accuracy.toFixed(0)}%一路稳定升至${latest.accuracy.toFixed(0)}%。这正是科学学习路径与孩子努力同频共振的证明。` };
    } else if (preTest && latest.accuracy > preTest.accuracy) {
        return { status: 'improving', title: '首尾进步型', content: `太棒了！对比课前测（正确率${preTest.accuracy.toFixed(0)}%），宝贝在第${latest.unitNumber}课的正确率已提升至${latest.accuracy.toFixed(0)}%，${(latest.accuracy - preTest.accuracy).toFixed(0)}个百分点的跨越清晰展现了进步！` };
    } else {
        return { status: 'stable', title: '过程价值型', content: `值得点赞！从课前到第${latest.unitNumber}节课的全程学习，宝贝展现了出色的坚持与思考习惯。面对不断升级的挑战仍兴趣盎然，这份专注力是未来突破的最大潜力。` };
    }
}

export const getStudentSummaries = (rows: StudentDataRow[]) => {
  const map = new Map<string, any>();
  rows.forEach(r => {
    if (!map.has(r.real_name)) {
      map.set(r.real_name, { name: r.real_name, grade: translateGrade(r.package_grade), teacher: r.counselor_name, unitCount: 0, lastUnit: 0 });
    }
    const s = map.get(r.real_name)!;
    s.unitCount++;
    s.lastUnit = Math.max(s.lastUnit, parseInt(String(r.level_sequence), 10));
  });
  return Array.from(map.values());
};

import React, { useState } from 'react';
import FileUpload from './components/FileUpload';
import ReportView, { ThemeType } from './components/ReportView';
import StudentList from './components/StudentList';
import { StudentDataRow, ProcessedReportData, UserRole } from './types';
import { processExcelData, getAvailableUnits, CURRICULA } from './utils';

type AppView = 'upload' | 'list' | 'report';
export type TrendMetricType = 'accuracy' | 'passRate';

function App() {
  const [view, setView] = useState<AppView>('upload');
  const [role, setRole] = useState<UserRole>('counselor');
  const [rawData, setRawData] = useState<StudentDataRow[]>([]);
  const [reportData, setReportData] = useState<ProcessedReportData | null>(null);

  const [selectedStudentName, setSelectedStudentName] = useState<string | null>(null);
  const [availableUnits, setAvailableUnits] = useState<number[]>([]);
  const [unitRange, setUnitRange] = useState<{ min: number, max: number }>({ min: 1, max: 1 });
  const [currentTheme, setCurrentTheme] = useState<ThemeType>('default');
  const [selectedCurriculumKey, setSelectedCurriculumKey] = useState<string>(Object.keys(CURRICULA)[0]);

  // Persistent report options
  const [isChartZoomed, setIsChartZoomed] = useState(false);
  const [trendMetric, setTrendMetric] = useState<TrendMetricType>('accuracy');

  const handleDataLoaded = (data: StudentDataRow[]) => {
    setRawData(data);
    setView('list');
  };

  const handleSelectStudent = (studentName: string) => {
    const units = getAvailableUnits(rawData, studentName);
    if (units.length === 0) return alert('该学生没有有效数据');

    const min = units[0];
    const max = units[units.length - 1];
    setAvailableUnits(units);
    setUnitRange({ min, max });
    setSelectedStudentName(studentName);

    // Smart Curriculum Logic
    const studentRow = rawData.find(r => r.real_name === studentName);
    if (studentRow) {
      const studentGrade = studentRow.package_grade || '';
      const mappedGrade = studentGrade.toLowerCase().includes('one') ? '一年级' : 
                          studentGrade.toLowerCase().includes('two') ? '二年级' :
                          studentGrade.toLowerCase().includes('three') ? '三年级' :
                          studentGrade.toLowerCase().includes('four') ? '四年级' :
                          studentGrade.toLowerCase().includes('five') ? '五年级' :
                          studentGrade.toLowerCase().includes('six') ? '六年级' : '';

      if (mappedGrade && !selectedCurriculumKey.startsWith(mappedGrade)) {
        setSelectedCurriculumKey(mappedGrade);
      }
    }

    const processed = processExcelData(rawData, studentName, role, { min, max });
    if (processed) {
      setReportData(processed);
      setView('report');
    }
  };

  const handleSwitchStudentById = (userId: string | number) => {
    const student = rawData.find(r => String(r.user_id) === String(userId));
    if (student) {
      handleSelectStudent(student.real_name);
    } else {
      alert(`未找到 ID 为 ${userId} 的学员`);
    }
  };

  const handleUnitRangeChange = (min: number, max: number) => {
    if (!selectedStudentName) return;
    setUnitRange({ min, max });
    const processed = processExcelData(rawData, selectedStudentName, role, { min, max });
    if (processed) setReportData(processed);
  };

  const handleReset = () => {
    setRawData([]); setReportData(null); setSelectedStudentName(null); setView('upload');
  };

  return (
    <div className="min-h-screen pb-10 bg-slate-50 font-sans">
      <header className="bg-white border-b-4 border-indigo-100 py-4 mb-8 shadow-sm print:hidden">
        <div className="container mx-auto px-4 flex justify-between items-center">
            <h1 className="text-2xl font-black text-indigo-600 flex items-center gap-2 cursor-pointer" onClick={handleReset}>
                🎓 学习情况报告生成器
            </h1>
        </div>
      </header>

      <main className="container mx-auto px-4">
        {view === 'upload' && (
          <FileUpload onDataLoaded={handleDataLoaded} role={role} onRoleChange={setRole} />
        )}
        {view === 'list' && (
          <StudentList data={rawData} onSelectStudent={handleSelectStudent} onReupload={handleReset} />
        )}
        {view === 'report' && reportData && (
          <ReportView 
            data={reportData} 
            rawData={rawData} 
            onReset={handleReset} 
            onBack={() => setView('list')} 
            availableUnits={availableUnits}
            currentRange={unitRange} 
            onRangeChange={handleUnitRangeChange}
            currentTheme={currentTheme} 
            onThemeChange={setCurrentTheme}
            selectedCurriculumKey={selectedCurriculumKey}
            setSelectedCurriculumKey={setSelectedCurriculumKey}
            onSwitchStudentById={handleSwitchStudentById}
            isChartZoomed={isChartZoomed}
            onToggleZoom={() => setIsChartZoomed(!isChartZoomed)}
            trendMetric={trendMetric}
            onToggleMetric={(m: TrendMetricType) => setTrendMetric(m)}
          />
        )}
      </main>
    </div>
  );
}

export default App;

import React from 'react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { UnitData } from '../types';

interface Props {
  data: any[]; // Use any to allow passed unitName
  color?: string; // Hex code for the main line
  isZoomed?: boolean;
  metric?: 'accuracy' | 'passRate';
}

const ReportChart: React.FC<Props> = ({ 
  data, 
  color = '#f97316', 
  isZoomed = false,
  metric = 'accuracy'
}) => {
  const metricKey = metric;
  const classMetricKey = metric === 'accuracy' ? 'classAccuracy' : 'classPassRate';
  const label = metric === 'accuracy' ? '作答正确率' : '通过率';

  const chartData = data.map(d => ({
    name: d.unitNumber,
    fullName: d.unitName,
    value: d[metricKey],
    classAverage: d[classMetricKey] 
  }));

  // Calculate dynamic Y-axis domain if zoomed
  const getYDomain = (): [number, number] => {
    if (!isZoomed || chartData.length === 0) return [0, 100];

    const allValues = chartData.flatMap(d => [d.value, d.classAverage]).filter(v => typeof v === 'number');
    if (allValues.length === 0) return [0, 100];

    const minVal = Math.min(...allValues);
    // Add a small buffer of 5% but stay within 0-100
    const start = Math.max(0, Math.floor(minVal - 5));
    return [start, 100];
  };

  return (
    <div className="w-full h-full flex flex-col font-sans">
      <div className="flex-grow min-h-0">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={chartData}
            margin={{ top: 20, right: 30, left: 0, bottom: 20 }}
          >
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e7e5e4" />
            <XAxis 
              dataKey="fullName" 
