const calculateRankings = (allRows: StudentDataRow[], range: { min: number, max: number }, role: string) => {
    const studentMap = new Map<string, { accuracies: Record<number, number>, totalScore: number, avgAccuracy: number, count: number, id: any }>();
    allRows.forEach(r => {
        const isHT = role === 'headteacher';
        const unitSeq = parseInt(String(r.level_sequence), 10);
        const lessonSeq = parseInt(String(r.unit_sequence), 10);
        if (isHT) { if (unitSeq !== range.max) return; } else { if (isNaN(unitSeq) || unitSeq < range.min || unitSeq > range.max) return; }
        if (!studentMap.has(r.real_name)) { studentMap.set(r.real_name, { accuracies: {}, totalScore: 0, avgAccuracy: 0, count: 0, id: r.user_id }); }
        const e = studentMap.get(r.real_name)!;
        const rate = parseRate(r.answer_right_rate);
        e.accuracies[lessonSeq] = rate;
    });
    const res = Array.from(studentMap.entries()).map(([name, v]) => {
        let totalScoreHT = 0; let totalCounselorAcc = 0; let countCounselor = 0;
        if (role === 'headteacher') { [0, 1, 2, 3, 4, 5].forEach(l => { if (v.accuracies[l] !== undefined) totalScoreHT += v.accuracies[l]; }); } else {
            Object.values(v.accuracies).forEach(val => { totalCounselorAcc += val; countCounselor++; });
        }
        return { name, userId: v.id, accuracies: v.accuracies, totalScore: Math.round(totalScoreHT), avgAccuracy: countCounselor > 0 ? totalCounselorAcc / countCounselor : 0, rank: 0 };
    });
    if (role === 'headteacher') { res.sort((a, b) => b.totalScore - a.totalScore); } else { res.sort((a, b) => b.avgAccuracy - a.avgAccuracy); }
    res.forEach((r, i) => r.rank = i + 1);
    return { rankings: res, total: res.length };
};

