                </div>
            </div>
        </div>

        {/* Ranking Section */}
        <div className="bg-white p-10">
            <div className={`${t.cardClass} border-2 ${c.border} overflow-hidden shadow-sm`}>
                <div className={`${c.rankingHeaderBg} p-6 border-b flex justify-between items-center`}><h3 className="text-2xl font-black flex items-center gap-3"><ListOrdered className="w-8 h-8 text-stone-400"/>正确率排名</h3><span className="font-bold text-xs opacity-40">共有 {total} 名学员参与统计</span></div>
