                                        <td className="px-6 py-5"><span className={`w-9 h-9 rounded-2xl flex items-center justify-center font-black ${r.rank <= 3 ? 'bg-amber-100 text-amber-600' : 'bg-slate-100 text-slate-400'} ${isMe ? 'ring-4 ring-amber-400/20' : ''}`}>{r.rank}</span></td>
