                                        <td className={`px-6 py-5 font-black text-sm font-mono opacity-50`}>{r.userId}</td>
                                        {isHT && rankingLessonCols.map(col => (<td key={col} className={`px-2 py-5 text-center font-bold text-[10px] ${col === 0 ? 'bg-amber-50/30 border-r-2 border-amber-100/50' : ''} ${r.accuracies[col] !== undefined ? 'text-slate-600' : 'text-slate-200'}`}>{r.accuracies[col] !== undefined ? `${r.accuracies[col].toFixed(0)}%` : '-'}</td>))}
                                        <td className="px-6 py-5 text-right font-black text-lg whitespace-nowrap">{isHT ? r.totalScore : `${r.avgAccuracy.toFixed(1)}%`}</td>
                                    </tr>
                                );
                            })}
                        </tbody>
                    </table>
                </div>
                <div className={`${c.rankingBannerBg} ${c.rankingBannerText} p-8 text-center font-black text-sm italic leading-relaxed`}>{getRankComment()}</div>
            </div>
        </div>

        {/* Footer */}
        <div className={`${c.teacherSection} p-12 text-center relative overflow-hidden`}>
            <div className="relative z-10 max-w-3xl mx-auto">
                <MessageCircleHeart className="w-12 h-12 mx-auto mb-6 opacity-40"/>
                <p className="text-2xl font-black italic mb-4 opacity-90 leading-snug">“ 学习不仅是分数的累积，更是思维的破壳而出。亲爱的家长，宝贝正在用每一个百分点的进步，书写属于自己的未来！让我们共同呵护这份成长。 ”</p>
                <p className="font-bold opacity-60">— 您的辅导老师 {data.teacher}</p>
            </div>
        </div>
      </div>
    </div>
  );
};

