                </>
              )}
            </div>
            <div className="p-8 border-t bg-slate-50/50 flex justify-end gap-4"><button onClick={() => setIsEditingMetadata(false)} className="px-8 py-3 rounded-full font-black text-slate-400 hover:text-slate-600 transition-colors">放弃修改</button><button onClick={handleSaveMetadata} className="px-12 py-3 bg-indigo-600 text-white rounded-full font-black shadow-lg hover:bg-indigo-700 transition-all flex items-center gap-2"><Check className="w-5 h-5"/>确认并同步</button></div>
          </div>
        </div>
      )}

      {/* Main Report Container */}
      <div 
        ref={reportRef}
        id="report-container-main"
        className={`${c.bgMain} ${t.containerClass} ${c.border} overflow-hidden relative print:shadow-none print:border-none print:rounded-none transition-all duration-700 mx-auto print:w-full`}
      >
        {/* Header */}
        <div className={`${c.headerBg} py-12 text-center relative border-b-4 ${c.border}`}>
            <h1 className={`text-4xl font-black ${c.headerText} tracking-tight drop-shadow-sm flex items-center justify-center gap-3`}>
                {currentTheme === 'boy' ? <Rocket className="w-10 h-10 animate-pulse"/> : <Crown className="w-10 h-10 text-yellow-300 fill-current"/>}
                {data.studentName} {isHT ? `专属学习报告` : `${currentRange.min}-${currentRange.max}单元 学习报告`}
            </h1>
        </div>

        {/* Profile & Badges */}
        <div className={`flex flex-col md:flex-row border-b-4 ${c.border}`}>
            <div className={`w-full md:w-1/3 ${c.profileBg} p-10 border-b-4 md:border-b-0 md:border-r-4 ${c.border} flex flex-col justify-center`}>
                <div className="flex items-center gap-4 mb-8">
                    <div className={`w-16 h-16 rounded-3xl flex items-center justify-center border-4 shadow-sm ${currentTheme === 'boy' ? 'bg-blue-600 text-white border-blue-200' : 'bg-rose-100 text-stone-500 border-white'}`}><User className="w-8 h-8"/></div>
                    <div><h3 className="font-black text-2xl">学员档案</h3><p className="text-xs opacity-40 font-bold uppercase tracking-widest">Profile Card</p></div>
                </div>
                <div className={`${t.cardClass} bg-white p-8 space-y-6`}>
                    <div className="flex justify-between items-center border-b pb-3"><span className="font-bold opacity-40">姓名</span><span className="font-black text-xl leading-none">{data.studentName}</span></div>
                    <div className="flex justify-between items-center border-b pb-3">
                      <span className="font-bold opacity-40">年级</span>
                      <span className="inline-flex items-center justify-center px-4 h-7 rounded-full bg-slate-100 font-bold text-sm leading-none">{data.grade}</span>
                    </div>
                    <div className="flex justify-between items-center"><span className="font-bold opacity-40">老师</span><span className="font-bold leading-none">{data.teacher}</span></div>
                </div>
            </div>

            <div className={`w-full md:w-2/3 ${c.badgesBg} p-10`}>
                <div className="flex items-center gap-3 mb-8"><Trophy className="w-8 h-8 text-amber-400"/><h3 className="text-2xl font-black">{isHT ? '学习成长勋章' : '荣誉成就'}</h3></div>
                {isHT ? (
                    <div className="grid grid-cols-2 gap-6">
                        {data.htBadges?.map((badge: Badge) => (
                            <div key={badge.name} className={`${t.cardClass} bg-white/80 backdrop-blur-sm p-4 flex flex-col items-center justify-center shadow-sm`}>
                                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center mb-2 shadow-sm ${currentTheme === 'boy' ? 'bg-blue-600 text-white' : 'bg-rose-50 text-rose-300'}`}>
                                    {badge.level === 'progress' ? <Zap className="w-6 h-6"/> : badge.level === 'potential' ? <Rocket className="w-6 h-6"/> : <Star className="w-6 h-6"/>}
                                </div>
                                <h4 className="font-black text-sm mb-1 leading-none">{badge.name}</h4>
                                <div className="flex gap-0.5 mb-2">
                                    {[...Array(5)].map((_, i) => (<Star key={i} className={`w-3.5 h-3.5 ${i < (badge.stars || 0) ? 'text-yellow-400 fill-yellow-400' : 'text-slate-200 fill-slate-100'}`} />))}
                                </div>
                                <p className="text-[10px] font-bold text-slate-400/80 text-center leading-tight italic">“{badge.description}”</p>
                            </div>
                        ))}
                    </div>
                ) : (
                    <div className="flex gap-10">
                        <div className="flex-1 flex flex-col items-center">
                            <div className={`w-28 h-28 rounded-[2rem] flex items-center justify-center shadow-lg transform rotate-3 mb-4 ${currentTheme === 'boy' ? 'bg-amber-400 border-4 border-white' : 'bg-rose-50 border-rose-100 border-2'}`}><Star className={`w-12 h-12 ${currentTheme === 'boy' ? 'text-white' : 'text-rose-300'}`}/></div>
                            <p className="font-black text-lg mb-2 leading-none">{data.completionBadge.name}</p>
                            <div className={`${t.cardClass} bg-white/60 p-4 text-center text-xs font-bold leading-relaxed`}>{data.completionBadge.description}</div>
                        </div>
                        <div className="flex-1 flex flex-col items-center">
                            <div className={`w-28 h-28 rounded-[2rem] flex items-center justify-center shadow-lg transform -rotate-3 mb-4 ${currentTheme === 'boy' ? 'bg-blue-600 border-4 border-white' : 'bg-amber-50 border-amber-100 border-2'}`}><Target className="w-12 h-12 text-white"/></div>
                            <p className="font-black text-lg mb-2 leading-none">{data.accuracyBadge.name}</p>
                            <div className={`${t.cardClass} bg-white/60 p-4 text-center text-xs font-bold leading-relaxed`}>{data.accuracyBadge.description}</div>
                        </div>
                    </div>
                )}
            </div>
        </div>

        {/* Learning Records & Chart */}
        <div className="flex flex-col lg:flex-row">
            {/* Table */}
            <div className={`w-full ${isHT ? 'lg:w-[45%]' : 'lg:w-[55%]'} border-b-4 lg:border-b-0 lg:border-r-4 ${c.border} bg-white p-8 flex flex-col`}>
                <div className="flex flex-col mb-8">
                    <h3 className="text-2xl font-black flex items-center gap-3 whitespace-nowrap"><BarChart2 className="w-8 h-8 text-indigo-500"/>{isHT ? `${data.studentName}同学 学习记录` : '学习闯关记录'}</h3>
                    <div className="mt-2 inline-flex items-center justify-center px-6 h-8 bg-indigo-50 rounded-full text-indigo-600 font-black text-xs w-fit leading-none shadow-sm">
                        一节课20分钟，短时高效，每天练出效果！
                    </div>
                </div>

                {/* HT Mode Error Comment Card */}
                {isHT && data.errorAnalysis && (
                  <div className="mb-6 p-5 bg-rose-50 rounded-[1.5rem] border-2 border-rose-100 shadow-sm animate-in slide-in-from-left duration-500">
                    <p className="text-xs font-bold text-rose-800/80 leading-relaxed italic">“{data.errorAnalysis.content}”</p>
                  </div>
                )}

                <div className={`${t.cardClass} border-2 overflow-hidden flex-grow`}>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm">
                            <thead className={c.tableHeader}>
                                <tr>
                                    <th className="px-4 py-4 text-left">单元内容</th>
                                    {!isHT && <th className="px-4 py-4 text-center">学习关联</th>}
                                    <th className="px-4 py-4 text-center">学习时长</th>
                                    {!isHT && <th className="px-4 py-4 text-center">学习分析</th>}
                                    {isHT && <th className="px-4 py-4 text-right">错误统计</th>}
