                                            {!isHT && <td className={`px-4 py-5 text-center font-black text-[11px] whitespace-nowrap leading-none ${u.status === 'low' ? 'text-slate-300' : 'text-indigo-500'}`}>{u.analysis}</td>}
                                            {isHT && (
