  const handleExportImage = async () => {
    if (!reportRef.current) return;
    setIsCapturing(true);

    try {
      // 深度优化：使用 html-to-image 实现像素级 1:1 还原
      const options = {
        quality: 1,
        pixelRatio: 2,
        backgroundColor: currentTheme === 'boy' ? '#f8fafc' : '#ffffff',
        // 强制固定宽度以匹配桌面级设计
        style: {
          width: '1200px',
          maxWidth: '1200px',
          margin: '0',
          padding: '0',
          transform: 'none',
        },
        // 设置为 false 告诉库不要因为跨域 CSSRules 无法读取而报错中断
        preferredFontFormat: 'woff2',
      };

      // 预热字体加载（html-to-image 常见坑：首次截图字体不全）
      await htmlToImage.toPng(reportRef.current, options);
      const dataUrl = await htmlToImage.toPng(reportRef.current, options);

      const res = await fetch(dataUrl);
      const blob = await res.blob();

      try {
        await navigator.clipboard.write([
          new ClipboardItem({ 'image/png': blob })
