            <div className={`w-full md:w-2/3 ${c.badgesBg} p-10`}>
                <div className="flex items-center gap-3 mb-8"><Trophy className="w-8 h-8 text-amber-400"/><h3 className="text-2xl font-black leading-none">{isHT ? '学习成长勋章' : '荣誉成就'}</h3></div>
                {isHT ? (
