                            <div className={`w-28 h-28 rounded-[2rem] flex items-center justify-center shadow-lg transform -rotate-3 mb-4 ${currentTheme === 'boy' ? 'bg-blue-600 border-4 border-white' : 'bg-amber-50 border-amber-100 border-2'}`}><Target className="w-12 h-12 text-white"/></div>
                            <p className="font-black text-lg mb-2 leading-none text-center">{data.accuracyBadge.name}</p>
