                    <h3 className="text-2xl font-black flex items-center gap-3 whitespace-nowrap leading-none"><BarChart2 className="w-8 h-8 text-indigo-500"/>{isHT ? `${data.studentName}同学 学习记录` : '学习闯关记录'}</h3>
