    if (ratio <= 0.2) return "表现优异！已进入班级第一梯队，继续保持稳健的步伐，冲刺巅峰！";
    if (ratio <= 0.5) return "进步显著！你正走在稳步提升的阶梯上，离尖子生行列仅一步之遥！";
    return "潜力无限！保持专注与耐心，每一份汗水都会在未来的考试中开出灿烂之花！";
  };

  return (
    <div className={`max-w-6xl mx-auto my-6 font-sans ${c.textMain}`}>
